local addon = WoWKoreanClient
if not addon.active then return end
local text = addon.worldText.speech
if not text then
    text = { values = {}, templates = {} }
    addon.worldText.speech = text
end
local rows = text.values
rows["89:2095346550"]="이 땅의 평화롭고 친절한 사람들을 보라 그들은 얼라이언스에 속하기 위해 태어났습니다."
rows["89:2095808141"]="우리는  ⁇ 를 자랑스럽게 섬기고 적을 물리칠 수 있는 모든 걸 할 것입니다."
rows["89:210895932"]="서리늑대 무덤이 공격받고 있습니다! 저지하지 않으면 얼라이언스에게 넘어갈 것입니다!"
rows["89:2117022837"]="우리 문 앞에 적들이 있어도, 빛 그리고 결정의 노래는 우리를 견지해 왔습니다."
rows["89:2125174472"]="우린 알파, 우리는 플라야스, 우리는 길네아스 출신입니다. 늑대, 나 'earties, aaaa-ooo!"
rows["89:2128603640"]="내 차번에 네 베이컨을 불에서 꺼내지 않을 수도 있어"
rows["89:2131012258"]="내 형제들이 미쳤어, 여기서 나가는 데 도움이 될 수 있을까?"
rows["89:2140579596"]="잠깐 멈추고 얘기하는 걸 좋아하긴 하지만 이 폭발물은 스스로 움직이지 않을거야"
rows["89:2142108981"]="이제 6주째 풀려났어요."
rows["89:225852471"]="좋을 대로 하시오. 하지만 안에 들어가려거든 최소한 세 명은 나를 도와야 하오. 따라오시오..."
rows["89:230284929"]="네가 빛을 볼 수 있을 거로 생각했다, 고드프리... 어서 말해라, 이 악마 같으니. 뭐라고 적혀 있지?"
rows["89:251904065"]="감히 서리늑대 사령관을 요새 밖으로 끌어내시겠다? 말도 안 되는 소리!"
rows["89:258160835"]="저 밖에서는 조심하는 게 좋을 거야. 많은 모험가들이 늪으로 갔다가 돌아오지 못했지. 딸꾹!"
rows["89:261372974"]="넌 챔피언이 됐어, 너랑 타이틀을 지키기 위해 필요한 걸 갖고 있다고 생각하니?"
rows["89:263256074"]="감히 누가 나의 성소를 더럽히는가? 경고하노니, 침입자는 모두 파멸을 맞으리라..."
rows["89:264475692"]="내가 농촌 소년이기 때문에 내 팔이 엄청 강해"
rows["89:265836723"]="스카우트, 섬에 필요한 건물을 짓는 사람들에게 말해주세요."
rows["89:290780153"]="빛 베레디드 워터즈 근처의 크리스탈 홀에서 어업 트레이너 에렛을 찾을 수 있습니다."
rows["89:295533947"]="전투에서 너무 느려져 있어, 더 잘 해야 할 것 같습니다."
rows["89:296790958"]="비밀은 없네, 안두인 윈, 부상을 허락하면 같이 가자"
rows["89:305303881"]="악마의 일에 개입하는 것은 이제 끝납니다."
rows["89:310951233"]="드래곤 키우는 거$B$B이 아름다운 사람들이 자라면 내 멍청한 형제는 내게 아무것도 안할 거야!"
rows["89:314359896"]="잘 됐어요, 그 결정이 내려지면 내가 준비될게요. 너무 늦지 않길 바랍니다."
rows["89:336410016"]="카힐, 정말 힘겨운 일이야."
rows["89:351033758"]="난 부끄러움이야 마그모트에서 농부와 함께 죽어야 했어$B$B내 생각을 맡겨라"
rows["89:35416612"]="일단 투여 과정을 완성하면 Y'Shaarj의 힘으로 우리는 막을 수 없을 것입니다!"
rows["89:366377585"]="%s 정렬하고 숲으로 가는 전에 인정하는  ⁇ 을 내린다."
rows["89:367053908"]="스노우 리리, 돌고래에서 왔어"
rows["89:3738761"]="곧  ⁇  라이 정상회담과 모든 판다리아는 분노로 가득차게 될 것이고, 그 다음에는 세계!"
rows["89:377248767"]="황과 화석의 냄새가 난다 이 포털은 악마들만큼 더러운 거야"
rows["89:388090031"]="이 계획은 가장 멍청한... 반 엉덩이... 미소적인 계획이야"
rows["89:403115252"]="병든다면 페스트러와 얘기해봐요"
rows["89:440493640"]="카르다쉬의 토테마는 우리의 것이 되면, 우리는 여러분의 도시를 파괴하고 다시 우리 도시로 만들 것입니다."
rows["89:442851317"]="엘룬은 나에게 기술과 경험을 선물해 줄 수 있다고 판단했으니 이제 전 그 기술을 당신에게 전달할 것입니다."
rows["89:443204400"]="Sir, 폭발과 총격으로 우리가 빠져나갔다고 생각합니다."
rows["89:44626265"]="내가 먹을 것이 있어, 너희가 배고프면 내 텐트를 이용하면 쉬게 될 수 있다."
rows["89:450090230"]="새  ⁇ 을 세웠고... 다시 도망치지 말라고 가르쳐 줄 방법이 많아요"
rows["89:451377141"]="에타스, 최고의 아크마거들이 이 장치를 한번에 연구해보고 싶어"
rows["89:451674696"]="제게는 불운만을 안겨준 검입니다. 어쩌면 당신은 그 힘을 다룰 이를 찾아낼지도 모르죠."
rows["89:452810438"]="그만, 내가 얘기해 줄게."
rows["89:455623046"]="잠시 쉬는 곳을 찾아야 해요 계속해"
rows["89:459143706"]="곰은 아름다운 존재야 야생하고 강한 전투에서 거칠고 우리처럼"
rows["89:465372896"]="브라이츠스피어 장관은 윈터스프링의 켈 테릴의 유적들 사이에서 방황하고 있습니다."
rows["89:465680972"]="이제 배울 것은 다 배웠군! 모두 배웠어! 이제 너와 끔찍한 피 봉우리와도 작별이다."
rows["89:470863934"]="이 전쟁은 엄청난 결과를 초래할 것입니다."
rows["89:473999786"]="왕을 위해 요리하는 건 영광이야, 직업이 아니야"
rows["89:476509080"]="여름철 불 축제는 모험을 할 수 있는 좋은 시간이지만 쇼핑을 할 수 있는 좋은 시간이기도 합니다!"
rows["89:477210484"]="다 끝났어 맥주 공장 뒷문에서 두 마리를 만나자"
rows["89:480805656"]="여러분, 느껴지십니까? 관중석이 후끈 달아올랐습니다! 곧 전투가 시작되겠군요!"
rows["89:486470444"]="음, 어쨌건 신세를 좀 진 것 같네요. 여기, 이거 하나 받으세요. 저한텐 많이 있으니까."
rows["89:48675241"]="귀환할 거야, 귀여운 친구"
rows["89:497345214"]="이 광물을 찾아내기 위해 너무 가까이 왔어요"
rows["89:501905185"]="오류: 보호된 메모리에 쓰려고 시도 해"
rows["89:502755141"]="난 도망치지 않을 거야 내가 널 이리 끌어들여서 죽였어"
rows["89:50560427"]="내가 드레드 로더와 상담을 하고 있는데 우리가 논의하는 것은 당신 문제 아냐"
rows["89:510353796"]="아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨"
rows["89:514712450"]="잘 싸웠어, 학생. 당신은 정말로 내 길을 구현해줬습니다."
rows["89:51844779"]="잡히기 직전에 이 부적을 찾았어요. 당신에게 유용할지도 모르겠네요..."
rows["89:519424095"]="네, 네... 얼라이언스 전사들, 당신은 사자를 대장으로 선택했습니다."
rows["89:524946799"]="조금 손상됐지만, 좋은 정보를 얻을 수 있을 겁니다."
rows["89:540056692"]="제발, 말의 동굴에서 찾아봐요. 언덕 위로 올라가서 말할 시간이 있을 때!"
rows["89:555146860"]="서스롱 랜치가 제 도움이 필요해요"
rows["89:558752317"]="스톰파이크 무덤이 공격받고 있습니다! 저지하지 않으면 얼라이언스에게 넘어갈 것입니다!"
rows["89:559431891"]="준비이 끝나고 다시 돌아와서 축제를 즐길 수 있을 거야"
rows["89:563843118"]="볼진은 딴 걸 하지 않고 바다 마녀를  ⁇ 고 싶어"
rows["89:569374993"]="그  ⁇ 을 치고, 이 사제들에게 네가 어떻게 만들어졌는지 보여줘"
rows["89:578746422"]="<알리시아의 몸은 물 속에서 부드럽게  bobs. 그녀는 오래 전에 죽은 것 같습니다.>"
rows["89:579594423"]="괴물 한 권의 책으로 군대의 승리에 대한 모든 페이지가 빈번하게 되어있죠"
rows["89:591011000"]="지금 당신의 장군이 그 벨을 보고 있을 거야?"
rows["89:591896878"]="어리석은... 너희가 성공했다고 생각하나? 이제 한 발짝 더 다가왔을 뿐이다. 끝없는 심연으로!"
rows["89:594483354"]="테라모어로 가는 포털을 구제하는 법을 배우고 싶다면"
rows["89:603665672"]="악병은 서서히 그들의 몸에 침투하여 점차적으로 그들의 회귀를 준비합니다."
rows["89:606049611"]="내가 갈게, 하지만 내 사람들한테 증언할 거야"
rows["89:612370989"]="그들은 강한 만큼이나 잔인합니다. 또한 존재하는 모든 것을 파괴하려 합니다."
rows["89:617918692"]="밀리 주변 바람은 빠르게 올라오고 나무가 비거게 됩니다."
rows["89:632739517"]="죽은 자들의 부활... 얼어붙은 북쪽 땅에서 온 언데드. 로데론의 도시들이 통째로 사라지는... 그런... 믿을 수가 없지만..."
rows["89:640276610"]="정말 인상적 인 기술입니다. 당신은 용사 계급을 받을 준비가 되어 있다고 생각합니다."
rows["89:641458189"]="난 이 날을 오랫동안 기다렸어, 우린 도전자 반지에서 마주쳐야 해"
rows["89:663244680"]="싸우고 싶다면 좀 더 강해질 때 다시 와$b$b하지만 지켜볼 수 있어"
rows["89:667217740"]="%s는 생각을 통해 하늘을 스캔하고 혀를 클릭하며 공기를 냄새가 맡고 눈물을  ⁇ 습니다."
rows["89:671387351"]="계속하면 난 채소를 키우는 비밀을 알려줘야지"
rows["89:678720931"]="< 복잡한 스케마트는 당신의 소박한 공학 재능을 알아차릴 수 없을 만큼 너무 많습니다.>"
rows["89:69817894"]="그 마법은 당신의 얼음 만질로 인해 속임수를 늦추는 것이 아니라면 더 위험하지 않을 것입니다."
rows["89:718290193"]="내가 아는 걸 가르쳐 주겠다, 하지만 먼저 작은 일을 해줘"
rows["89:722829548"]="두 번째 단계: \"통증의 물들, 내 부르짖음을 듣고 토르자리의 바네를 낳아라!\""
rows["89:72318902"]="항상 영 키스 물을 가져가야 돼"
rows["89:734365459"]="난 저 아래에서 비행기들을 만들고 있는 게 아니라 가나오 수집을 담당해야겠어!"
rows["89:747609158"]="이렇게 썩은게 안 들어올 수 있어 먼저 그 못생긴 고기를 씻어내야 돼"
rows["89:750153074"]="모든 게 계획대로 진행되고 있습니다."
rows["89:754503212"]="너 같은 짐승의 미간에 화살을 박아줄 정도의 나이는 먹었다... 지금의 두 배나 되는 거리에서도 말이지."
rows["89:759195044"]="다른 사람들은 나를 찾아내면, 다른 사람들처럼 울고 죽을 것이다."
rows["89:764595677"]="이 여행자들은 강도기에 준비가 되어 있습니다! 그들의 물건을 가져가십시오! 그들의 모든 것을 가져가십시오!!!"
rows["89:768787022"]="난 방랑한 대화에 시간이 없어 훈련해야 할 남녀가 있고, 지켜봐야 할 탑이 있어"
rows["89:76926631"]="...그리고 다른 klan의 지원을 받지 않고도 자신의 개인 경호를 지휘했나요?"
rows["89:780369139"]="그리모테마는 페라라스에도 숨어있으며, 이 캠프에 공격할 기회를 기다리고 있습니다."
rows["89:804330844"]="어, 당신은 모든 생명을 구하기 위한 열쇠가 될 수 있는 칼림도어 물고기로?"
rows["89:819445852"]="너희 힘 따위는 아루갈 님의 힘과 비교조차 되지 않는다! 내가 직접 너희를 없애버리겠어!"
rows["89:831420224"]="판드랄! 때가 왔다! 에메랄드의 꿈속에 숨어서 기도나 올려라!"
rows["89:834965284"]="이런 건 좀 더 자주 해야 돼."
rows["89:837703538"]="다시 꿈꾸었나? 7개의 눈을 가진 검은 염소"
rows["89:843559825"]="난 공격에 참여할 준비가 됐어 케리토스"
rows["89:846863983"]="파티 좀 끼어도 괜찮겠지? 옛 친구들도 몇 명 데려왔어!"
rows["89:847935054"]="좋은 소식으로 피륨 로드스턴로 돌아가서 곧 스톤하어스에서 만나게 되죠"
rows["89:85265643"]="텔드라시일 병에 걸렸을 때도 그런 건 본 적 없어"
rows["89:862883675"]="누가 살아 있는 불의  ⁇ 을  ⁇ 을 할 수 있겠는가? 나는 네 몸에서 너의 본질을  ⁇ 겠다!"
rows["89:869326699"]="여기 방문객이 많지 않네, 주방으로 튀김 좀 사면 좋겠나?"
rows["89:869673804"]="넌 여기 있지 않아, 물은 보호되어야 돼..."
rows["89:873903841"]="저게 워프 게이트를 해체하는 데 도움이 되고 싶네요 불타는 군단 남쪽 진영?"
rows["89:875891952"]="기프트스?$B$B맛있는 술은 뭐야?"
rows["89:886873900"]="네놈이 뭘 하려는지 내가 모르리라 생각하느냐? 네놈이 무슨 짓을 하고 다녔는지 못 본 줄 아느냐?"
rows["89:891477305"]="축복받은 십자군 깃발이 세워졌습니다.\010모든 공격으로부터 깃발을 보호해야 합니다."
rows["89:891780825"]="내 Fist of Fury에 연결된 소리 증강 장치에 들어와"
