rows["90:1002817574"]="영웅들, 우린 스트라थो름을 가지고 있어"
rows["90:1017571105"]="우린 거의 출발할 준비가 됐어요 준비 좀 더 해 주세요"
rows["90:1022600318"]="고통 받은 용의 식습관 이 얼마나 맛있는지 알아보십시오. 공포에 떨고 있는 육류만 충분할 것입니다."
rows["90:1024500942"]="당신들의 유신들은 여기, 어린 시절을 보낸 장소에서 모였습니다!"
rows["90:1028787028"]="뚱보, 벽에 구멍이 가득한 거품 속에 살기를 고집하는 이유가 있나요?"
rows["90:103201629"]="이봐, 이봐, 블랑쉬. 사과 하나 가지고 부러워할 거 없어. 넌 조만간 멋진 모험을 떠나게 될 테니까 말이야."
rows["90:1034523187"]="환영합니다, 뱀 라이더!"
rows["90:1034707861"]="피의 바다, 파괴된 도시! 우리는 누구인가?"
rows["90:1038008547"]="아라코아족은 그들이 가진 모든 암살자를 보낼 수 있습니다. 그들은 이들과 같은 운명을 맞이할 것입니다!"
rows["90:1038770020"]="조심해, 젠다라리들이 벽을 뛰어넘어!"
rows["90:1040096171"]="어릴 때 좀 쉬웠지만 요즘은 더 조심해야 해요"
rows["90:1049559776"]="시간이 이 섬에 영향을 주지 않는다고 합니다."
rows["90:1070081300"]="기억해야 할 중요한 것은 우리가 모두 폭발에 대한 사랑 때문에 여기 있다는 것입니다!"
rows["90:1078694712"]="그 수정 조각에서 발산되는 악의 기운이 거대괴수 중 하나를 끌어들이고 있습니다. 당장 그걸 내려놓으십시오!"
rows["90:108068781"]="너희는 한 민족의 짐을 어깨에 짊어지고 그들이 너희에게 어떻게 보답하였는가?"
rows["90:1092995367"]="경주 경로를 표시하는  ⁇ 판은 있지만 다른 경로를 찾는 것에 대해 처벌받지 않습니다."
rows["90:1094456880"]="그는 그의 보좌에 앉아, 평화의 꿈을 가지고 자신의 겁쟁이를 은폐하는 것에 만족합니다!"
rows["90:1098401039"]="배에서 탑승하는 게이트로 가는 길을 열어주면, 우리는 걸어서 갈 필요가 있습니다."
rows["90:1099154948"]="그리고 제왕후 셰크지어가 우리 나라에 무슨 짓을 하는지 봤을 때 설득할 필요도 없어"
rows["90:1109836797"]="저는 여러분들이 알고 싶고 얼라이언스 이 캠페인에 대한 저의 전폭적이고 확고한 지지를 받고 있습니다."
