rows["90:1114758860"]="서쪽으로 배달되어야 할 마지막 폭약도 소식이 없어. 이 게으름뱅이들이 어디서 뭘 하고 있는 거지?"
rows["90:1132356137"]="얼굴이 파란색이 될 때까지 얘기해봐, 난 아타말 크리스탈을 너에게 주지 않을거야."
