rows["90:1170633482"]="그 똥구멍이 날 페니스 케프에서 쫓아냈어 나도 내 캠프에서 쫓아질 수 없어!"
rows["90:1174162513"]="이 일은 너무 멀리 갔어요 스컬지 공격 언더시티더 많은 사람들이 오기 전에 파괴해!"
