rows["90:1983390917"]="작은 거품들을 뛰어 넘어서 에디의 |cFFFF0000|Hspell:110189|h[Watery Shield]|h|r를 약화시키십시오!"
rows["90:1986271010"]="넌 옳은 곳으로 왔어, 내 친구!"
rows["90:198799769"]="나루의 긴급 차단 시스템이 가동되면 마나괴철로를 영원히 쓸 수 없게 된다. 그러니 반드시 취소해야 한다!"
rows["90:1995036339"]="이 일은 너무 멀리 갔어요 스컬지 공격 스톰윈드더 많은 사람들이 오기 전에 파괴해!"
rows["90:20115558"]="썬더 킹은 타이탄 경호자의 힘을 가지고 있습니다."
rows["90:2017283744"]="그 다음 어둠이 와서 땅으로 흘러들어왔고 천천히 우리를 감염시키고窒息시켰습니다."
rows["90:2017994660"]="평화가 있어, 내 아들아 아직 네 시간이 오지 않아 여기서 남아서 앞으로 일어날 일을 지켜봐라"
rows["90:2020017176"]="새로운 신병들이 도전할 수 있는지 알아봐"
rows["90:2025209998"]="우리 힘을 합쳐야 했지만 라그나로스를 다시 불지방으로 밀어 넣었습니다"
rows["90:2044797358"]="좀 더 빨리 움직여라, 이 하찮은 것들! 주인님께서 찾고 계신 아타말 수정을 찾지 못하면 그분의 분노를 사게 될 것이다."
rows["90:2060051957"]="이 잡기를  ⁇ 려고 했는데, 정말 멋질거 같아"
rows["90:2060377374"]="자, 무엇이 더 무서운지 보자. 깨어날 때 꿈꾸는 것이나, 살아있는 악몽 속에서 깨어나가는 것이!"
rows["90:2084038322"]="이번 꿈에서 나는 세상에서 제일가는 어부였답니다. 그리고 칼림도어라고 불리는 곳으로 갔지요..."
rows["90:208545329"]="조심해,  ⁇ - ⁇ ! 강한 바람이 바다로 날릴 수 있어!"
rows["90:2090228203"]="어떻게 내 왕좌 방으로 침입해서 이 음모적인 말도 안되는 것을 퍼뜨려보려고 할 수 있는 용기가 있어요!"
rows["90:2092896823"]="우리는 이 가스 폭발적인 불안정을 완화시켜서 엄청난 압력을 가했습니다."
rows["90:2103485549"]="감히 내 집에서 나에게 도전하다니 아무리 용이라지만 오만함이 하늘을 찌르는구나!"
rows["90:2110404911"]="록타르! 두 번째 경비탑이 무너졌다! 마지막 경비탑을 파괴하면 적은 금세 퇴각할 것이다!"
rows["90:212331998"]="이 상처에서 회복되기까지는 시간이 걸릴 겁니다. 하지만, 살아있어서 다행입니다."
rows["90:2137458119"]="자폭 가동 장치의 코드명은 \"큰 적색 단추\"로서, 미미론 자신의 발명품입니다."
rows["90:2144983701"]="또다시, 너는 알지 못하느냐? 내가 나 자신을 위하여 명성을 얻었으니, 나는 완전함을 만들었느니라"
rows["90:2146781767"]="남부 던 발다르 참호가 공격받고 있습니다! 저지하지 않으면 호드에 의해 파괴되고 말 것입니다!"
rows["90:215483227"]="우린 몇 주 더  ⁇ 근 시간만 일해야 돼"
rows["90:219028334"]="난 네 여보를 데려갈게"
rows["90:219951789"]="흑마술사가 완전히 다른 모습으로 변하며 사악한 미소를 흘립니다."
rows["90:220143924"]="당신은 일을 끝낼 위해 돌아왔습니까? <라토리크 웃음> 오브시디온 상승 및 그들을 파괴!"
rows["90:2231683"]="필요한 시기에 도움을 보내야 합니다. 뉴 타라나르에 대한 공격이 임박합니다!"
rows["90:23129993"]="다가가 포기하지 않을 거야 우린 친구들을 찾아서 그들을 위해 싸워야 해"
rows["90:239880912"]="알았다, 아락세스. 지원을 보내겠다. 현 위치에서 대기하라. 반복한다. 현 위치에서 대기하라."
rows["90:254445603"]="바리안 폐하. 제이나 님. 와주셔서 감사합니다. 원형경기장에 자리를 마련했습니다."
rows["90:272164928"]="네 손아귀로 무고한 이들에게 고통을 주던 일도 이제는 끝이다. 내 이름을 걸고 맹세하는데 널 죽이고 말겠다."
rows["90:299938978"]="우리 앞에 있는 전투에 집중해 두면 남은 일에 대해 걱정할 수 없을 거야"
rows["90:330431719"]="왕을 들었어, 라인을 강화해줘 영웅들이 가로쉬를 찾아갈 시간이 필요해"
rows["90:339842772"]="인고, 난 당신 사람들을 보호하기 위해 막대를 줬어"
rows["90:340383703"]="말리 휠러 경이 왕실 사거리에서 다른 전투장들과 함께 있어요"
rows["90:341441971"]="침입을 용서해 주시오, 레이디 프레스터. 하지만 고왕 볼버는 당신의 조언을 구하라고 제안했습니다."
rows["90:34319389"]="강이 절벽을 만나는 것처럼 가을에는 아름다움이 있습니다."
rows["90:359375259"]="뒷마당에서 어린 윙어 스냅퍼를 들었어요"
rows["90:359855505"]=" ⁇ 메지스 크시렘은 당신 같은 사람들과 거래하지 않습니다."
rows["90:360596483"]="아레나에도 들어오는 '더크 소문'은 진짜 이름도 없는데"
rows["90:361177163"]="판다렌 풍선보다 훨씬 크죠."
rows["90:369315853"]="아니, 하지만 우리 모두 죽을 것이라는 것을 알기 위해 내가 그것을 볼 필요가 없습니다!$b$b내 말 들어?\010"
