rows["90:404674067"]="혼자 싸우지 못했을 거고, 이제 내 차를 찾아 가야겠어"
rows["90:411318975"]="나가와 Twilight Cult은 함께 일하고, 이 노력의 중심이 될 것입니다."
rows["90:414677586"]="조심해, 이 홀 너머에는 당신 세상에서 들어보지 못한 위험들이 있습니다. 조심스럽게 가세요."
rows["90:420784645"]="그렇지 않아도 심장이 약한 편이라 잘 놀라는데... 자꾸만 놀라게 하는군... 하지만 다음번에는 단단히 준비하고 있을 거야!"
