rows["90:450081123"]="당신께 봉사하기 위해 부르신 이 모든 것들은 무엇이며, 당신들은 누구라고 생각하십니까?"
rows["90:450979587"]="술에 취한 오크가 볼 수 있는 곳이고 술에 취한 오크 군대는 다시는 볼 수 없는 곳이다"
rows["90:464703754"]="전선에 방문하지 않은 게 너무 오래 됐어요"
rows["90:473797442"]="내가 당신을 훈련시킬 생각은 없어요. 당신이 익소다르의 우호가 될 때까지요."
rows["90:481020039"]="힐드 마스터는 크리스토퍼 드라쿠일입니다."
rows["90:488500801"]="오그레들과 싸우면 내가 싸울 거야"
rows["90:489313964"]="군주께서 이 사실을 아시면 크게 노하실 것이다. 너를 해치워 그분의 분노를 식혀 드려야겠다."
