rows["90:529171669"]="내가 운전을 가르쳐 줄 때까지 빌그워터 카르텔의 괴물들과 함께 기쁜 거요"
rows["90:533257132"]="우리가 여기서 끝나면, 얼라이언스은 그들이 이 땅에 발을 내딛지 않았으면 좋겠다."
rows["90:535123894"]="이봐, 지금 좀 바쁘네요."
rows["90:535640921"]="그때부터 가끔씩 사람들이 그가 그들에게 말을 하고 눈을  ⁇ 라고 주장합니다."
rows["90:537270609"]="아무도 갑작스러운 움직임을 하지 마, 우린 그냥 항복을 협상하고 평화롭게 떠날 거야"
rows["90:542164207"]="그렇지요오. 바다사냥꾼은 우리가 여기까지 왔다는 사실에 기뻐할 거예요. 불의 군주가 지배하는 힘이 약해지리라 생각해요."
