rows["90:564570237"]="살마 살디언의 한 잔을 사면 안되는 게 뭐죠? 서부 몰락지대 지금쯤에  ⁇ 을 먹어"
rows["90:571650609"]="당신 이 바랄 때, 좋은 일이지만, 아직 당신 이 같은 사람들과 훈련할 준비가 되지 않았습니다. "
rows["90:579395082"]="전 이 모든 흥분으로 눈을 감았습니다.$b$b이 일이 한 마일 떨어진 곳에서 왔을 때..."
rows["90:586765620"]="내 거야! 내 거! 내 거! 여기서는 기즐록이 두목이다! 절대로 내 존재를 알리지는 못해!"
rows["90:596676889"]="말도 안 돼, 하지만 그 벌레들은 우리 군대를 살려주기 위해 많은 노력을 기울일 겁니다."
rows["90:610356937"]="어떻게 우리 준비를 방해할 수 있는 용기가 있어?"
