rows["90:622980615"]="크랭 스톤호프는 마을의 남동쪽 모퉁이에 자신의 훈련 회로를 타고 서 있습니다."
rows["90:623349046"]="우리는 델 아이슬스로 행진할 준비를 하고 있습니다."
rows["90:626368328"]="이 존재들은 자기들끼리 스톰윈드 복권의 당첨 번호도 알려주지 않는답니다."
rows["90:633881638"]="벨의 통세에 그것은 될 것입니다 1:00내가 해방되면 이 도시를 찢어 버릴 거야!!!"
rows["90:635644271"]="내가 자유클에게 그들을 죽이기 위해 부탁하지만, 난 약한 새끼들을 얻는다!"
