rows["90:676030842"]=" ⁇ 스칼프 장관이 내가 죽으면 보상할 수 없어"
rows["90:694936456"]="이 곳은 싸움을 시작하기에 적합하지 않죠. 그렇지 않으면 아무도 이 음식을 즐기지 못할 겁니다."
rows["90:700351754"]="이번엔 우리를 막는 데 성공했을지도 모르지만, 우리는 돌아올 것입니다."
rows["90:7082752"]="열에 두 마리가 싸우고 있어, 방해가 되고, 미끄러지고, 삐걱거리고, 빠져나와!"
