rows["90:747942766"]="무력하고 무력하고 회복해야 할 제브림의 통제를 이 고통에 종식시켜야 한다"
rows["90:759434177"]="한번 더 춤추면, 내가 떠나야 돼"
rows["90:777711447"]="알 수 없는 발굽 자국에, 검게 그을린 방패, 휘장은 떨어져 있고... 이 모든 현상을 어떻게 이해해야 하겠습니까?"
rows["90:7853727"]="이제 반쯤 된 일을 그만두지 마, 나 도망가면 안전하냐는 걸 말해줘!"
