rows["90:790105052"]="네가 심하게 다쳤을 때, 쉬고 다시 힘을 얻으라"
rows["90:795256401"]="구원은 정의와 진실에 속한 자들로 함께하여 구원을 받으리라"
rows["90:798757096"]="뱀 마스터가 되는 길은 어려운 거니까 도전할 준비가 되셨나요?"
rows["90:805840748"]="그늘 쉼터 여관으로 가서 흔적을 찾아보고 그 흔적이 어디로 이어지는지 확인한 후 돌아와서 내게 보고하시오."
rows["90:814089104"]="... 헤어젤을 구매하기 위한 기금을 만들자고요? 뭣 때문에요? 전 제 머리가 맘에 드는걸요!"
rows["90:817009377"]="어찌 그걸 잊겠습니까. 잘 들으세요, 우서. 역병에 대해 얘기할 게 있습니다."
rows["90:827947499"]="잘했어, 부메바. 얼라이언스 다 잔달라를 막는 데 도움이 되길 원해요"
rows["90:828058111"]="보통 이 해안은 안개가 덮여 있어 어떤 이유로 가해졌던 것 같습니다."
rows["90:832987497"]="우린 예전의 어린아이들 아냐, 마나리! 빛, 우리는 당신의 고통을 끝낼 것입니다!"
rows["90:835759352"]="네, 당신은 리더가 될 것 같군요. 얼라이언스?"
rows["90:855310078"]="내가 끝냈다고 생각했는데, 감사하고, 그리고 순서에 감사해요."
rows["90:857361174"]="낙사나르에서는 잠시 물러났을 뿐이다! 보주의 힘으로, 발라나르는 복수를 행하리라!"
rows["90:861691219"]="엔지니어들은 종종 달라란 북서부 마구스 무역 거래소에서 시계처럼 훈련합니다."
rows["90:871051641"]="힘을 유지하려면 잘 먹어야 해요. 엄마도 항상 그랬어요."
rows["90:874494468"]=" ⁇ 을 꺼내라, 미누스 디그스는 우리에게 고고학 수업을 줄 거야"
rows["90:875884094"]="그 크기를 봐요, 이번 주에서 가장 큰 모리야"
rows["90:886634761"]="많은 큰 갈등이 이 습지에서 발생했습니다. 저는 여전히 그 에너지를 느낄 수 있습니다."
rows["90:889162169"]="고개를 숙여라, 하찮은 벌레들이여! 너희들의 연약한 영웅 따위는 아무것도 아니다! 너희들의 구원자를 자처하는 녀석들은 우리의 첫 번째 제물이 될 것이다!"
rows["90:909577973"]="고왕과 그의 챔피언들과 암흑철의 왜성들이 함께 일해 아이언포지."
rows["90:913984000"]="우두우는 아버지의 힘입니다 호드다 스프릿스 골짜기는 볼진의 통제하에 있습니다! "
rows["90:924736541"]="이 생명체는 섬을 보호하는 번개 발작에 면역력이 있습니다."
rows["90:924752631"]="그 검에 입을  ⁇ 어봐, 모그라인."
rows["90:926616744"]="너무 자신만만한 것 아닌가? 지난번에 우리 만났을 때를 생각하면 그런 말 하기 쉽지 않을 텐데."
rows["90:942190633"]="당신은 미친 사람이거나, 거칠고, 아니면 전설이라고 불리는 영웅이 되죠."
rows["90:947312181"]="이 시즌 농장은 비어있어요. 지혜로운 농부는 땅이 언제 휴식을 취할 수 있는지 알고 있습니다."
rows["90:947915630"]="이제 물의 비밀이 알려졌어요. 이 선물을 마을을 돕기 위해 사용하겠습니다."
rows["90:950871268"]="사람들은 내가 왕이라고 생각해서 내게 다가왔어요"
rows["90:955854917"]="동북부 장벽에서 영웅의 계곡을 바라보는 곳에 그립폰 마스터를 찾을 수 있습니다."
rows["90:957484771"]="그 영이 우리에게 미래를 보여줬고, 어떻게든, 그것은 당신과 관련이 있습니다."
rows["90:980927646"]="외계인은 드물고, 더 드물게는 떠있는 죽음의 배에 도착하는 외계인이 있습니다."
rows["90:985332569"]="다른 사람을 위해 사용하는 힘은 적에 쓰는 힘보다 두 배 더 강력합니다."
rows["90:98725729"]="베이커 마스터슨이 가장 재능 있는 요리사가 아닐까?"
rows["90:987533640"]="판다리아의 자녀들아, 안개가 떨어졌어."
rows["90:998422507"]="너도 네 욕심을 채우려고 영혼을 거두는구나. 용사여, 너와 내가 정말 그렇게 다른 존재일까?"
rows["91:1005844899"]="당신들의 상사들 앞에 굴복하고, 이 소소한 세상의 멸망을 살아남을 수 있습니다!"
rows["91:1014029238"]="우리에겐 도전자가 있어, 우리의 작은 포로가 할 수 있는 일을 보여줘야 해!"
rows["91:101424676"]="권한 없는 존재가 회로 과부하 시도 중. 대인 방어 장치 가동."
rows["91:1021077775"]="해냈군요! 푸른용군단을 몰아내고 그들의 사령관을 없애셨습니다! 대단하군요!"
rows["91:1023076438"]="난 아무것도 아니야, 난 아무도 아냐, 난 약자야$b$b난 아무것도 아니야, 난 아무도 아냐, 난 약자야$b$b난 아무것도 아니야"
rows["91:1025585906"]="우린 항상 동맹을 필요로 해요. 난 당신을 배반하는 바보일 거야, 특히 전쟁 때"
rows["91:1027947451"]="팬더가 우리를 사냥하고 있어, 한 곳에 머무르는 건 좋지 않아."
rows["91:1064053893"]="기둥 위에, 나는 그를 보았다. 죽음의 날개. 궁극적인 대결의 시간이 왔었다."
rows["91:1071090446"]="나가들은 내 의지를 억압하고 있어 내가 그들이 하는 일을 느낄 수 있지만,"
rows["91:1080781525"]="준비되면 말해줘|TInterface\\GossipFrame\\GOSSIPGOSSIPICON.blp:32|t"
rows["91:1108177827"]="|cFFFFFFFF그들은 군대를 훈련시키고, 우리를 죽일 새로운 흥미진진한 방법을 가르치고 있습니다.|r"
rows["91:1120739317"]="네 작은 비밀이 있어, 칸레타드 난 네가 아는 걸 요구하니까"
rows["91:114090638"]="그래, 그래. 흠, 다른 학술서도 참고해야겠는걸. 저것도 찾아봐야겠어."
rows["91:1143947530"]="난 전쟁주인 블러드힐트의 이름으로 왔는데 곧 도착할 거라는 것을 알려주고 싶어"
rows["91:1145520548"]="크라우리 스텔 지장과 크라우리 오르크하드에서만 산마을을 타고 갈 수 있습니다."
rows["91:1152406075"]="도와줘서 고마워요, 더 이상 변신하지 마요, 치유를 위해 노력하겠습니다!"
rows["91:1156222172"]="넌 나나 무드클라우야, 난 엄마한테 방문할 줄 몰랐어"
rows["91:1169438671"]="실버문의 은행은 바자르 안에 있습니다. 동남쪽 모퉁이에 찾아보세요."
rows["91:1171090267"]="정말 흥미롭군... 이렇게 평범한 족쇄가 엄청난 마법의 힘을 지니고 있다니..."
rows["91:1171261271"]="저와 저희 마을을 대신해서 두 분께 감사를 드려야겠습니다. 두 분께서 어떤 일을 해내셨는지 많은 이들이 모를 테지만 말입니다."
rows["91:1176746729"]="말푸리온은 소리치지는 않을 수도 있지만, 그는 당신의 사람들의 도착에 대해 매우 걱정했습니다."
rows["91:1184624060"]="멍청한 놈들... 동생의 나약한 감정을 이용하면 구조 대원을 보낼 줄 알았지."
rows["91:1196986365"]="신병들에게 빨간색 셔츠를 주지 않으면 안 돼"
rows["91:120299253"]="적을 직접 만나지 않아 지능을 더 많이 사용해서"
rows["91:1203628556"]="그래, 역시 힘에 대한 내 생각이 맞았어. 이 주제에 대해 다른 학술서에는 뭐라고 쓰여 있는지 한번 볼까?"
rows["91:1214228705"]="전투에서 죽는 건 영광이지만 내가 가르쳐준 것만으로도 빨리 죽지 않을 수 있겠지?  "
rows["91:122541198"]="아하하, 위대한 니우자오, 서양의 힘, 신성한 천성, 약한 사람들의 보호자..."
rows["91:1230925990"]="우리 집 위해 싸워서 우리의 것을 되찾을 거야"
rows["91:1235774614"]="우리는 화이프들이 우리의 일을 수행하는 것에 익숙해져 있습니다."
rows["91:1240706035"]="당신의 의지와 반대해서, 당신은 |cFFFF0000|Hspell:122398|h[안버 폭발]|h|r!"
rows["91:1249783277"]="우리는 도움을 주려고 왔지만, 아직은 우리에게 그들의 호의를 베풀지 않은 것 같습니다."
rows["91:1260758338"]="\"나무가 얼마나 좋은가, 펜릭. 우리에게 은신처를 제공한단 말일세.\"라고? 나무를 안 베고 어떻게 해결하라는 건지."
rows["91:1265453129"]="안녕, 귀여운 아가씨 부탁해 바론에게 내가 뭘 해야 할지 물어봐"
rows["91:1273343463"]="전 현장 작업에 대해 별로 좋아하지 않았습니다. 특히 트롤들이 엄청나게 많을 때요."
rows["91:1283460729"]="우리 마그하르를 찾아 주다니 더 없는 영광이오, 듀로탄의 아들이여. 대모님께서는 피난민 병동에서 기다리고 계시다오."
rows["91:1290383711"]="빛은 고통이 아무도 원하지 않습니다, 내 자녀. 하지만 그것은 우리의 영역에서 무제한으로 통치하지 않습니다."
rows["91:130614784"]="희망,  ⁇ 드랄이 우리 민족을 다시 영광으로 되돌려놓은 희망처럼?"
rows["91:1314014336"]="아직 때가 아닌데 나를 너무 일찍 깨웠도다, 이그젝큐투스, 대체 왜 이런 불경한 짓을 저지른 게냐?"
rows["91:1314797613"]="내가 운전을 가르쳐 줄 때까지 빌그워터 카르텔의 괴물들과 친근하게 지내야 해"
rows["91:1318952140"]="타우르 아헤에서 '크래클링 자이드 라이트닝'을 어떻게 말해야지? 태라스시아어? 나즈야?"
rows["91:1319538064"]="네 번째나 세번째로 내가 미친 스턴트 중 하나를 시도하면서 거의 절 죽였나요?"
rows["91:1322981569"]="지금도 내 힘은 강해지고 있다. 오랫동안 복수를 완성할 날만을 기다려 왔다."
rows["91:1332066113"]="경각심을 갖고 있어, 영웅."
rows["91:1336059142"]="끝없이, 내 의지를 꺾어 자신을 섬기고 그 검과 결속되게 하려 애쓰더구나..."
rows["91:1343365263"]="마치 악몽에서 깨어났던 것처럼 느껴지지만, 그 곳의 그림자는 여전히 남아 있습니다."
rows["91:1345094961"]="너무 많이  ⁇ 어요! 너무 많은 테라핀 오일을 넣은 것 같네요. 다시 시도해보세요!"
rows["91:1348779767"]=" ⁇ 이 났어? 나는 젖었어!"
rows["91:1349848867"]="메우, 난 고양이  ⁇ 이니까 날 안 들어봐요 내가 널 지칠 수도 있어요"
rows["91:1350022934"]="- 잠깐만요, 빨리 기어 헤드 만들죠!"
rows["91:1355260559"]="다음 말을 현명하게 선택해, 크라우리 날 부인하면 그녀는 영원히 나를 위해 봉사할 거야"
rows["91:1356494468"]="< 부상당한 군인은 여전히 숨을 쉬고 있는 것 같습니다. 다행히도, 그녀의 거품은 그대로 남아 있습니다.>"
rows["91:1362576140"]="다쳤어, 발자격해줬어,  ⁇ 어봤어, 아무것도 없어서 잊혀진 걸 깨지 못해"
rows["91:1370124971"]="저는 한때 위대한 전투가 있었습니다. 노인이 제게 너무 많은 기술을 빼앗지 않았으면 좋겠습니다."
rows["91:1398448185"]="많은 것이 아니지만 내가 가진 작은 것을 빌려주겠습니다. 마지막 시간에 도움이 되길 바랍니다."
rows["91:1398592841"]="내 느낌을 믿을 수가 없었다. 너무나 여러 번 리치 왕에게 속았기 때문에 말이다."
rows["91:1398683042"]="저는 \"로어워커\"입니다. 제 민족의 역사학자입니다."
rows["91:1402505611"]="젊은 전사들이여, 마지막 시험을 치를 때가 왔다! 이제 가장 힘든 전투를 준비하도록."
rows["91:1410409605"]="내가 바로 공격했을 것이고, 승리에 대한 내 급기 때문에 더 많은 사람들이 목숨을 잃었을 것이다."
rows["91:1415047542"]="전 전투에서 죽을 예정이었어... 다른 날 따라와 회복할 때까지"
rows["91:141807354"]="돌난로 무덤이 공격받고 있습니다! 저지하지 않으면 얼라이언스에게 넘어갈 것입니다!"
rows["91:1421535137"]="냄새가 나기 좋은 토푸, 와서 냄새가 나기 쉬운 토푸를 가져오세요!"
rows["91:1425313786"]="작은 돌을 던질 때까지는, 하지만 곧 물결이 온 호수를 덮어 버립니다."
rows["91:1428048198"]="역시 생각했던 대로군. 이 보석과 목걸이는 그다지 중요한 게 아니오. 중요한 건 마력원천이오."
rows["91:1434858109"]="좋은 소식이에요, 여러분! 아제로스의 모든 생명체를 파괴할 역병을 완성했어요!"
rows["91:1440040622"]="먼저 내 보조들에게 대항해 자신을 증명하고 그들을 물리치고 나서 나를 마주할 수 있다."
rows["91:1445950800"]="다른 포로가 화산에 있습니다. 희생되고, 더 나쁜 것은 좀비화되고 있습니다!"
rows["91:1446874971"]="또한, 데스트루크토바이트와 그의 미묘한 거품 홀로그램 기계가 무대에 들어오고 있습니다!"
rows["91:145668504"]="이 거북이 평화를 이해하지 못해 우리 마을을 죽여버릴 거야"
rows["91:1457519226"]="애완동물을 따라오라고 명령하는 것을 잊지 마세요! |TInterface\\Icons\\ABILITY_TRACKING.BLP:24|t"
rows["91:1459927111"]=" ⁇ 가트, 네 괴물들이 이 배의 지지를 더 벗으면 파도에 빠져들게 될 거야!"
rows["91:146151870"]="숲이 당신 존재를 말해줬지만 왜 여기 왔는지 말하지 마"
rows["91:1471371309"]="그의 명령을 따르라 불타는 군단-  ⁇ 어지면 죽게 될 거야!"
rows["91:1472837223"]="저한테서 멀리, 저생의 쓰레기!"
rows["91:1474367683"]="내가 할 모든 일을 그녀에게 말해야겠어?"
rows["91:1474977287"]="그럼 역사에 대한 당신의 지식을 시험해 보겠습니다. 영웅, 죽은 자 없는 무르락들이 어떻게 불리나요?"
rows["91:1496763851"]="왜 괴물 같은 작은 생물들은 항상 더 큰 생물에 매료되는 걸까요?"
rows["91:1520775676"]="정말 날 이길 수 있다고 생각했나? 네 친구도 곧 보내 주마, 탤런."
rows["91:152502548"]="그리고 당신은 영웅적인 특징으로..."
rows["91:152701536"]="만약 당신이 준비되어 있고, 정상 시간 흐름으로 빨리 돌아가고 싶다면, 나는 당신을 운송할 수 있습니다."
rows["91:1529930147"]="<아카네 수호자는 동남부 하부 도시의 열린 시장으로 내려갑니다.>"
rows["91:1532579545"]="어떻게 우리의 삶이 지금 더 나아지지 않는다고 말할 수 있을까요?"
rows["91:1538724057"]="내가 한 명만이 아니라 다른 사람들이 많이 있습니다."
rows["91:1541283150"]="샐리, 리틀 루, 계획이 바뀌었지 암버를 주 캠프로 데려가야 해"
rows["91:1548641905"]="영웅들이여, 나를 도와다오. 더는... 더는 저들을 붙들어 둘 수 없다. 이 상처를 치유해다오!"
rows["91:1579004880"]="5분 휴식 시간이야 농담이야 얼라이언스?!"
rows["91:1588091528"]="더 똑똑한 다지크 팁을 받을 시간이야. 선생님이 너무 힘들게 지워서는 안 돼. 이제 집으로 가자"
rows["91:1588980524"]="천연 수호자는 |cFFFF2222|Hspell:140068|h[ 치유 에너지]|h|r의 영역을 나타냅니다!"
rows["91:1589214473"]="여기 있는 스킨은 킬리안 헤이지라고 부르는데, 그는 내부 반지의 롤드클럽에서 일하고 있어요."
rows["91:1589701765"]=" ⁇ 링은 강하지만 걱정마, 네가 그를 싸운 후에 곧 내가 너와 함께해줄게"
rows["91:1598176620"]="크로마틱 비행은 침입자들을 처리할 것입니다. 더 긴급한 문제들에 대해 이야기 해 봅시다."
rows["91:1603509887"]="< 부상당한 군인은 여전히 숨을 쉬고 있는 것 같습니다. 다행히도, 그의 거품은 그대로 남아 있습니다.>"
rows["91:1606402107"]="챔피언의 계급에 아직 준비가 되지 않은 것 같네요."
rows["91:1607904896"]="그대와 그대의 친구는 전투 기술에서나 쐐기돌을 얻고자 하는 목적에서 그 자질을 증명해 보였다."
rows["91:1608511447"]="오늘 습지에서 쓰레기를 찾았어요"
rows["91:1614900419"]="이 녀석을 보세요. 지지를 다리 아래로 담대하게 서서, 저를 도전하려고 생각했어요."
rows["91:1617554779"]="그에 미치지 못하였으므로 이에 따라 판결하노라. 이제 일어나라, 저주받은 영주 일스카르여!"
rows["91:1619542433"]="블랙무어가 대체 너에게 무얼 기대하는지 모르겠군. 돈으로 살 수 있는 한낱 노예 따위에 불과한데 말이야."
rows["91:1634050769"]="그만! 이제 이 벌레들에게 내 혈통의 힘, 대지 그 자체의 분노를 보여주마."
rows["91:1635089981"]="당신의 생각들이 저를 흥미롭게 하고 있습니다. 당신의 행동이 목적이 있고, 당신의 복잡성은 인상적입니다."
rows["91:1638209596"]="스톰하트 왕은 날 얼음생처럼 시험하러 보냈어"
rows["91:1638216820"]="목소리가 너무 아름답고 가끔은 오케스트라 전체를 들을 수 있다고 맹세합니다"
rows["91:1643975997"]="조턴하임으로 돌아가서 뼈 마녀의 매력이 실패하는 것을 느낄 수 있습니다!"
rows["91:16479092"]="성공! 또 다른 부패한 용이 사라졌다! 곧, 죽음 날개만 일어설 것입니다."
rows["91:1648990216"]="흑마술사가 완전히 다른 모습으로 변하며 사악한 미소를 흘립니다."
rows["91:1668165749"]="내가 승인 할 수 없습니다 O' 소년 '자신으로 돌아다니는, 하지만 나는 그의 생각 이해."
rows["91:1680876928"]="하지만 전투에서 가장 중요한 건 힘겹게 얻은 승리를 어떻게 축하하느냐이다."
rows["91:1688056606"]="태양을 쳐다보지 못하기 위해 할 수 있는 건 다$b$b이 곳은 뭐죠?"
rows["91:1689607812"]="아버지와 아들, 어머니와 딸, 부모로서 우리는 우리의 유산을 자녀들에게 전하고 있습니다."
rows["91:1702084197"]="네 '백 호랑이 길'과 '제이드 뱀'의 기술도 내 기술만큼이나 잘해졌다고"
rows["91:1730613834"]="마침내 추방된 거미들이 돌아오는 시간입니다.$B$B다시 한번  ⁇ 메리건은 우리의 고향이 될 것입니다!"
rows["91:1735655001"]=" ⁇ 을  ⁇ 면 숨겨진 보물이 드러납니다."
rows["91:1736773737"]="내가 함정에 속인 걸 믿기지 않아"
rows["91:175905347"]="호세네, 항구들은 당신 책임이야."
rows["91:1759872327"]="악마를 더 강력하게 만들고 싶으면"
rows["91:1772594067"]="다크스피어는 절대 당신들한테 굴복하지 않을 거야, 자르지라"
rows["91:1779045547"]="난 영원히 돌의 손길이 거부됩니다. 난 다시 철의 영광을 알지 못할 것입니다."
rows["91:1788655374"]="이 모든  ⁇ 돌기 기술을 여기서 가져가야 돼 폭풍우가 우리를 공격하기 전에!"
rows["91:1791951471"]="이것은 정말 심각한 일입니다. 우리는 이 질병의 진정한 원인을 찾아내야 합니다."
rows["91:1792195174"]="캡틴은 아타스 왕자가 돌아오면 다시 로데론로 돌아갈 것이라고 말했습니다."
rows["91:1798461606"]="한 날, 그 사랑 받는 승려 는 동료 노예 들 에게 도전 을 내세워 \"나를 치라!\"고 외쳤다."
rows["91:1800827498"]="놈들이 다른 농부들을 모두 쫓아냈을지는 모르지만, 나 살딘은 절대 서부 몰락지대를 떠나지 않을 것이다!"
rows["91:1809240664"]="지휘관, 늑대 승마자들이 적군을 공격할 때가 됐습니다."
rows["91:1813774334"]="내가 초록을 먹기 전에 물어봐도 좋을 거야 다른 늑대가 공격하고 싶지 않아"
rows["91:1816239757"]="나르송 크로콜리스크는 사라졌어요. 파다렌들이 모든 이야기를 보지 못했기 때문입니다."
rows["91:1817769026"]="게제가 일을 하기 위해 왔고, 내가 여기 있어, 그가 일을 하는 동안 아무도 그를 괴롭히지 않도록 하기 위해서요."
rows["91:1821725793"]="정말 금수 전문성을 배워서 관련 레시피를 잃어버리고 싶으세요?"
rows["91:1824020499"]="시력이 없어질 수도 있지만, 모든 감각을 보상하는 나라에서 살고 있는 행운이 있습니다."
rows["91:1839174570"]="신비스러운지 아니든, 나랑 같이 여행하는 곳이 없을 거야"
rows["91:1845228302"]="해변을 가로지르는 경로는 순환되어 있어"
rows["91:1861477918"]="날씨가 악화되고, 초등병들이 곧 따라올 것입니다."
rows["91:1864072829"]="마을 남동쪽의 다리 근처에 체크하는 것을 잊지 마세요."
rows["91:1874302231"]="전투에 합류하는 것이 영광입니다."
rows["91:187829238"]="상자를 잘 처리하셨어요! 다음 임무를 알려 드릴 테니 스트라솔름 입구로 와서 제게 말을 거세요!"
rows["91:1888381957"]="안갯속이라 잘 보이지는 않지만, 네 냄새는 맡을 수 있지! 죽어라, 이 더러운 오우거 녀석!"
rows["91:1890747686"]="우린 이 광선을 스카이가드한테 줄 수 없어"
rows["91:190541269"]="순찰대원, 알시아 사령관에게 마을에 심각한 위협이 다가오고 있음을 보고 드리게. 어서 준비해야 하네!"
rows["91:1908860897"]="내 아들, 이 일에 나와 함께 해줘"
rows["91:1914612571"]="제 첫 번째 명령은 제가 예상했던 것보다 더 어려웠어요."
rows["91:1917423847"]="우리 가족은 수년간 무리를 해소해왔어요"
rows["91:1918946028"]="아, 여기 그 소년이야. 그는 특별해 보이지 않나요? 죽은 남편과 저는 항상 아이를 원했습니다."
rows["91:1932113791"]="트와일라이트의 해머 수사에서 도와드릴까요?"
rows["91:1936619240"]="자네가 할 일이 있어, 젤레 내가 잘할 수 있는 거 알아"
rows["91:1937087781"]="죄수들을 지켜줄 사람이 없어서 도망갈 수 없다는 걸 확인해야 했습니다."
rows["91:1959981082"]="운이 널 찾아내기 전에 포기할 마지막 기회야"
rows["91:1963659115"]="멍청한 놈들... 동생의 나약한 감정을 이용하면 구조 대원을 보낼 줄 알았지."
rows["91:1965260469"]="가장 큰 위험을 감수하는 사람은 가장 큰 승리를 거둘 수 있습니다."
rows["91:197527814"]="그래, 이게 바로 내가 알고 싶었던 거야. 이제 흐름의 변동에 대한 내용이 어디에 나와 있는지만 찾으면 되는데..."
rows["91:1979199292"]="잠깐 잠자리를 좀 잤어요."
rows["91:1982606610"]="여기 있어, 내가 생각했지 네가 이리 오기 전에 포버볼그들이 널 잡았을지도 몰라"
rows["91:2003364794"]="난 당신의 멋진 작전을 목격했지, 드라쿠루 언제 계획에 적용될거야?"
rows["91:2017959862"]="그로그가 배럴에서 빠져나오는데 많은 해적들이 이 일로 매우 불만을 가질 것입니다."
rows["91:2018421875"]="어둠의 순찰대만으로는 우릴 영원히 안전하게 지킬 수 없네. 스톰윈드 군대의 지원이 필요하네."
rows["91:201958339"]="이 저널은 왜성어로 쓰여져 있는데, 그 스크롤을 읽을 수는 없지만 한 가지 알아차릴 수 있습니다."
rows["91:201964385"]="강도의 골짜기 한가운데 은행 밖에서 사랑의 편지를 받을 수 있습니다."
rows["91:2033189790"]="멍청한 기뢰가 반사할 때 좋은 시간을 선택했지!"
rows["91:2037412073"]="배틀스카르밸리로 돌아오지 않으면 크롬가르 파괴기에서 제거될 거야"
rows["91:2037617051"]="이 일이 끝나면 다라란으로 가서 도시를 떠다니게 도와줄 거야"
rows["91:2038313023"]="해적들을 고용한 사람은 누구야? 이건 대단하네! 얼마나 큰 파티였지!"
rows["91:2044239476"]="생각할 시간이 필요하다... 원한다면, 너희의 임무에 힘을 빌려주겠다. 그만큼은 빚을 졌지. 잘 가라."
rows["91:2047657209"]="저는 실버문의 방어군 지휘관입니다. 그리고 제가 필요하다고 생각하면 도움을 요청하겠습니다! "
rows["91:2060012218"]="제 의무는 제 사람들을 보호해야 합니다. 전선에 있어야 한다면, 기꺼이 그렇게 할 것입니다."
rows["91:2063368011"]="스톰파이크 보급기지가 공격받고 있습니다! 저지하지 않으면 얼라이언스에게 넘어갈 것입니다!"
rows["91:2065768862"]="너무 그리워!$B$B대답할 거야 아니면 그냥 가만히 있어?"
rows["91:2067731077"]="계속  ⁇ 을 죽이면 고레렉처럼 성장해버리겠지"
rows["91:2078497692"]="그가 죽인 모든 고통과 고통은 무고한 사람들에게..."
rows["91:2079918569"]="마가타는 우리를 잘 이끌었고, 이 날이 올 줄 알았어요."
rows["91:2083678574"]="제 남편은 며칠 전에 야롱들이 포로로 잡혔습니다.$B$B지금 당장 위험해"
rows["91:2087240487"]="대영주님께서 만들어낸 그 틈은 열리자마자 네루비안 거미줄로 막혀버렸고 말입니다."
rows["91:208822883"]="반지 용기에 오신 것을 환영합니다. 준비를 끝낼 때까지 편안하게 지내세요."
rows["91:2094321129"]="정말 드물게 발견됐어요$B$B<마트레디스  ⁇ 니다>$B$B 계속하고 싶다면 부품이 필요해"
rows["91:2099725556"]="구조, 시공, 전력, 위험, 두 번 확인해"
rows["91:2107044462"]="놈을 잡아다 가죽을 벗겨 살점을 뜯어먹은 후 뼈를 하나씩 차례대로 부러뜨릴 것이다."
rows["91:2107389288"]="라저 언덕 동쪽에서, 바락 뒤에 두그루 고렐루스트를 찾을 수 있습니다."
rows["91:2109170620"]="전투장에서 필요해 콰일디르들이 우리 경계를 넘어서버렸어"
rows["91:2113799911"]="시어링 골목의 슬래그  ⁇ 의 어두운 철  ⁇ 은 많은 수의 잠금 상자를 가지고 있습니다."
rows["91:2125537724"]="네가 하는 일을 알 수 있어... 우리가 친절하게 대한다면 더 큰 말을 할 수 있을지도 몰라"
rows["91:2130343540"]="다리 건너서 문에서 드래그로 가는 거요"
rows["91:2132155734"]="이 경기도 실버문 시티가 늦어졌어요 스카우트를 보내면 되겠나?"
rows["91:213995300"]="이건 안 윈프러의 친구 신의  ⁇ 이 조각된 유물상입니다. 공포에 시선을 넓게 뜨는 모습이죠."
rows["91:217556381"]="용감한 승무원들은 가능한 한 빠르고 쾌적한 여행을 위해 최선을 다할 것입니다."
rows["91:22434605"]="모든 초들이 계산되길 바랍니다.\010가자고 준비되면 알려줘서 여기서 나가게"
rows["91:224646853"]="우리가 도착했을 때 이미 소환 룬이 그려져 있었으니 모두 파괴해야지"
rows["91:230249847"]="군대를 모아 호수로 가요, 하루가 끝날 때까지 베럴 백작이 파괴되길 바랍니다!"
rows["91:236357358"]="이 웬디고들은 짜증나게 하지만 진짜 싸움은 이 프로스트맨 난민들과"
rows["91:240765631"]="우리 앞에는 길이 있습니다.  ⁇  시 선생과 이야기해 다음으로 무슨 일이 일어날지 알려줄 겁니다."
rows["91:251374390"]="좋아요, 어서 서둘러 여기를 빠져나가요! 조금만 더 힘내요. 빠져나가서 쉬죠."
rows["91:256375228"]="내 뱀들, 이미 모든 바위 밑에  ⁇ 어다니고 있는"
rows["91:274330476"]="스피리톤 수장님, 너무 늦기 전에 서스레치 정상회담에 도움을 보내주세요."
