rows["91:948953257"]="썬더 블러프행 비행선이 도착했습니다! 불모의 땅을 가로질러 편안하게 여행하실 분은 모두 타세요!"
rows["91:963213468"]="안쪽은 잘되나봐, 공원이 깨끗하면 더 멀리 찾아볼게요"
rows["91:965910717"]="파티가 해적 테마를 가지고 있을 줄 몰랐어요"
rows["91:966267395"]="이건 경고일 뿐이야, 우리 중 한 명을 다시 때리면 잠에서 죽게 될 거야"
rows["91:975521074"]="더크문 섬에 오신 것을 환영합니다. 이 아름다운 짐승들 중 하나를 타고 페어까지 내려가세요."
rows["91:985004187"]="우리는 이 아기들이 다시 작동하도록 충분한 부품을 찾게 된 행운이었습니다!$B어떻게 도와드릴까요?"
rows["91:994458733"]="유동성 그린스톤 브루를 받았어 전투에서 여러 적을 물리치도록 도와줘"
rows["92:1004222441"]="이 항구에서, 용기는 스톰윈드와 럿테라인 마을 사이에 돌아갑니다."
rows["92:1006214614"]="뭔가 행동을 해야 하네. 스컬지가 우리를 몰살하기 전에 놈들에게 어떻게 대항할지 결정해야만 해."
rows["92:1009380018"]="그래, 브롬이 내 인생의 사랑이야."
rows["92:1016454451"]="돌고래를 죽였어?"
rows["92:1018197037"]="이렇게 멀리까지 올 수 있는 힘은 있어야 합니다."
rows["92:1020868935"]="이웃, 무산 짐승이 잘 안 돼?"
rows["92:1028230325"]="술 친구한테 가서 술 한잔하는 동안  ⁇ 에서 멀리 떨어져 있어"
rows["92:1034145798"]="엘라와 가장 친한 친구야."
rows["92:1047625319"]="만약 당신이 내 동료들을 연락하게 된다면,"
rows["92:105766489"]="충분하고도 남을 만큼 많이 있소. 만약 다른 물건이 필요하다면 주저하지 말고 요청하시오!"
rows["92:1078057720"]="안두인 왕자를 찾아서 열심히 일하고 있어요"
rows["92:1081422161"]="마그나타우르 땅을 침공할 용기가 있다면, 보네스부더가 기꺼이 널 꺾고 네 다리를 벌로 빼앗아갈 거야!"
rows["92:1086217129"]="볼진이 오고 있어 \" ⁇ 의 타핑\"은 몇 분 안에 열릴 거야"
rows["92:108859352"]="끔찍해요, 다들 죽었다고 생각해요$B$B어떻게 저  ⁇ 아미트를 지금 꺼내야?"
rows["92:1091370921"]="그들을 구하기엔 너무 늦었지 모르지만, 공격자들을 제거해 줄 수 있을지도 몰라"
rows["92:1093553364"]="너의 선조가 보이는구나, 수도자여! 그들은 어둠 속에서 몸부림치며 괴로워하고 있다... 너희 선조가 우리와 함께 있다!"
rows["92:1126876697"]="이 곳은 반짝이는데, 난 좋아하지 않아."
rows["92:1134901796"]="|TInterface\\Icons\\spell_shaman_staticshock:20|t%s |cFFF00000|Hspell:137149|h[부하]|h|r!"
rows["92:1137516362"]="네, 그리고 당신의 도움으로 우리는 이 땅에서 비밀을 파헤쳐낼 것입니다 호드!"
rows["92:1139494644"]="이건 잘 안 돼, 건물을 확보해야 돼!"
rows["92:1155729199"]="고제 보스는 당신 딸이라고 비난하고 즉시 처형하라고 명령했습니다"
rows["92:115865856"]="몇 개의 작은 영토를 되찾았어"
rows["92:1160400960"]="내가 내 시대에 많은 강력한 단어를 썼지만 여전히 가장 강력한 것은 내게 숨겨져 있다."
rows["92:1170271181"]="블랙록 산은 북쪽의 세어링 골리와 남쪽의 버닝 스테프스 사이에 위치하고 있습니다."
rows["92:1177527854"]="누가 당신에게  ⁇ 을 때리는 걸 말했나?"
rows["92:1181133458"]="네가 준비됐어... 보스를 만나기 위해 시간이야."
rows["92:1193872901"]="당신이 믿는 신에게 기도나 올리시오. 아마도 도와주러 올 거요. 하지만, 호드는 갈 수 없소..."
rows["92:1196883591"]="이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐, 이봐,$b$b하지만 그렇게 한다면... 저한테도 해"
rows["92:1200268850"]="그의 말, 나를 채워주십시오, 내 피가 비워지고, 당신은 뱀의 신의 영광에 목욕 할 것입니다!!!"
rows["92:120361500"]="빨리, 영웅! 우리는 아르헨트 유방에 돌아가서 공격이 다가올 것을 경고해야 합니다!"
rows["92:1213025326"]="네 손잡이들이 아버지를 머리를 잘라 죽인 걸 봤을 때 내가 그렇게 생각했나?"
rows["92:1214070600"]="도움이 필요하다면, 날 데려와줘서 도와줄게"
rows["92:1224710338"]="로맨틱한 연극은 정말 힘들지만 이번에는 더 잘할 거야 재능이 있어"
rows["92:1229180236"]="우리는 여기 숫자로 많이 우월하지만 잘 실행된 전략으로 성공할 수 있다고 믿습니다."
rows["92:1234425730"]="왜 갑자기 불모의 땅가 꽃을 피우게 되었는지 궁금하지 않습니까?"
rows["92:1238099757"]="내가 너라면 고블린 경주 상품을 사겠네"
rows["92:124858628"]="넌 나와 훈련할 수 없어, 낯선 사람 "
rows["92:1252417964"]=" ⁇ 돌이 침범됐어, 해더에게 가서 이 강탈자들을 파헤쳐라"
rows["92:1268074561"]="|TInterface\\Icons\\ability_hunter_posthaste.BLP:20|t|cFFFF0000|Hspell:146497|h[불태리]|h|r"
rows["92:126877516"]="용감한 영웅 여러분, 사건의 중심에 뛰어들기 위해 충분히 강합니다."
rows["92:1269980382"]="화려한데, 불꽃이 가득한 새끼 고양이보다 더 빨리 앞으로 나아갔어"
rows["92:1285027351"]="리치 왕의 군단이 점점 더 크게 규합되고 있다. 반드시 우리의 일정이 그분의 계획을 제대로 지원할 수 있어야만 한다."
rows["92:128869768"]="소그리의 팀에 들어가면 다른 사람들처럼 하위에서 시작해"
rows["92:1294425160"]="내 도움 없이 리치 왕을 물리칠 수 있을 것 같으냐? 나는 복수할 것이다... 녀석에게도, 너희에게도!"
rows["92:1297716411"]="해적날이야 내일 해가 뜨기 전까지 부티베이 내 거야"
rows["92:1303077132"]="수백 명이나 수천 명이나 될 수도 있습니다."
rows["92:1318669837"]="왜 내가 함정을 고칠까?"
rows["92:1330161612"]="하루 종일 \"모그를 죽여라\"라고 부르고 있어"
rows["92:1346652207"]="지구 어머니께서 부르시고 응답하실 겁니다."
rows["92:1347366663"]="날름이와 한 패가 되다니 어리석어! 너는 이제 광란심장 일족 친구 아니다. 광란심장 일족이 손 좀 봐줄 거야."
rows["92:1348327657"]="|TInterface\\Icons\\inv_misc_dust.blp:20|t%s는 |cFFFF0000|Hspell:124359|h[Burrow]|h|r로 시작됩니다!"
rows["92:1350017443"]="사울팽 님이 여기 계시잖아, 사가이! 브록시가르의 형제이신 사울팽님이 우리를 도우러 오셨다니까!"
rows["92:1354383155"]="내가 직접 죽이고 그 짐승의 피부를 벗었지"
rows["92:1357803994"]="넌 못생긴 게 아니야, 리리안... 우리 중 한 명이야."
rows["92:1358331539"]="트롤베인 혼자서는 연합한 오크족 호드를 이길 수 없습니다. 우리는 끝장입니다..."
rows["92:1360333834"]="혈통자 황진이 문에 침투하고, 궁전보호로 들어가지 못하게 해야 합니다!"
rows["92:1380226550"]="만약 당신이 이국적인 맥주 좀 필요하다면, 브루페스트의 T'chali의 우두 맥주 공장에서는 당신을 보호해 줄 수 있습니다!"
rows["92:1386401615"]="이런 동굴에서 살고 그 미친 호박을 따라다니는 것은 자연스럽지 않아!"
rows["92:1390437638"]="마라우돈은 서부 해안의 중심에 위치하고 있으며, 스피어스 계곡에 있습니다."
rows["92:1396193841"]="승무원이 목이  ⁇ 다면, 우리는 일시적으로 그들의 생리적 기능들을 안정시키기 위해 공기를 전달할 수 있습니다."
rows["92:1399152000"]="틀린 건 바로 너다! 이 성가신 주술사를 죽이고 나면 너희 둘도 처리해주마!"
rows["92:1407028416"]="능력에 대한 자신감은 큰 도움이 될 것입니다. 과잉 자신감은 빨리 당신을 죽일 수 있습니다."
rows["92:1438713580"]="셋 셀 때까지 썩 꺼지지 않으면 험한 꼴을 보게 될 것이다."
rows["92:1441463231"]="동 달라란의 거대한 톱니탑을 보십니까?"
rows["92:1443938787"]="기둥이 복원되면 이 영역은 안전합니다. 이제 표면에 있는 상처에 관심을 가져야 합니다."
rows["92:1452327024"]="이제 우린 친구가 됐으니 고백해야 해 농부 펑을 좋아할 것 같아"
rows["92:1452518883"]="챔피언, 적의 움직임을 예측하고 항상 한 발 앞서라. 승리는 당신 안에 있다!"
rows["92:1460450785"]="이 사람들은 우리의 동맹국들이야, 위협처럼 그들을 지켜봐라"
rows["92:146242512"]="나쁜 고기 때문에 병에 걸리는 사람들이 있다고 들었어요"
rows["92:1467959137"]="로어워커 쇼가 당신을 칭찬했고, 우리를 싫어하지 않는 한 환영합니다."
rows["92:1472842801"]="안녕하세요!$B$B우리로 합류하기 전에 몇 시즌 더 뒤쳐야지"
rows["92:1476981133"]="간단한 질문을 해볼게요. 남성이 자신의 눈 ⁇ 의 땀을 흘릴 수 있는 권리도 있나요?"
rows["92:1481434221"]="제가 전에 발견한 티탄의 다른 기록관과 비슷하군요. 음... 더 낡았고... 더 크다는 점만 빼면요."
rows["92:1484944808"]="무릎을 꿇고, 뚜 ⁇  달린 십자군은 Flameweaver의 시체를 조사하고 무언가를 찾고 있습니다."
rows["92:148615253"]="미안해, 좀 쉬는게 좋을 거야$b$b나즈그림에게 파티를 따라갈 거라고 말해"
rows["92:1487619821"]="이 곡물을 브루머 부프에게 가져와 축제를 시작할 수 있어 $p!"
rows["92:1526838496"]="이건 위험한 게임이야 금을 가져가지만 내가 지켜보고 있다는 걸 알아\010"
rows["92:1538520926"]="판이 무너지고, 판을 찢어내면 그를 쓰러뜨릴 수 있어요"
rows["92:153855039"]="장군님, 우리는 가로시와 대화를 나누기 위해 왔습니다."
rows["92:1538564600"]="파괴의 종들이여, 이 세상을 뒤틀린 황천!"
rows["92:1540241509"]="할루트가 말을 할 때마다 프렌지하트 힐에 내려놓고 싶어"
rows["92:1549832851"]="어째서 엉망이 되었어요? 어느 누가 수도원 요리에 말해주세요."
rows["92:1553233534"]="로어워커의 예술은 미묘함과 기술적인 전문성이 부족합니다."
rows["92:1559634632"]="넌 화려한 것처럼 보이네 내 친구"
rows["92:1559764617"]="고맙구나! 더 오래 버틸 수는 없었다... 끔찍한 일이 여기에서 일어났다."
rows["92:1569059220"]="6년 연속  ⁇  토스 대회에서 우승했고, 파다리아에서 가장 강인자입니다."
rows["92:1577897947"]="이봐, 이쪽은 믿기지 않네... 두 개나고 거친 놈들 포로와 티글을 알아?"
rows["92:1585189087"]="현재 공격이 진행 중이고, 또 다른 공격을 시작하기 전에 기다려야 합니다!"
rows["92:1587036203"]="그리고 여기 있네요, 그냥 물을 더해 주세요!"
rows["92:1594359732"]="바람이 진정되기를 기다려야 하고, 그리고 먼 거리의 코딩을 덮어야 합니다."
rows["92:1600418451"]="너 정말 큰 놈이라고 생각하니? 모두를 구하고 이 야만인 오크들과 친구가 되는 거야?"
rows["92:1600908460"]="블랙 프린스, 당신은 매우 강하지만 비전 없이 힘은 어떤 유익이 있을까요?"
rows["92:1601230589"]="아르헨트 십자군 전투가 시작됐어"
rows["92:160416770"]="헨델, 이제 자네 문제를 처리해야겠군. 프라우드무어 님께서 탑에서 자네에게 말씀하실 걸세."
rows["92:1628191210"]="돈도 없고 우리가 아는 것에서 멀리 떨어져 있는 얼어붙은, 죽은 자들로 가득한 북쪽 땅 가운데"
rows["92:1630583282"]="이제 모든 생명체의 포옹을 느낄 수 있습니다."
rows["92:1645166984"]="나가들이 우리 방구들을 뚫고 나가가 우리를 포위하고 있어"
rows["92:1669592137"]="아뇨, 제가 연구하고 있는 암부레이터 캠프파이어 프로토타입을 떠올리게 해"
rows["92:166965984"]="최첨단 전신전송기 때문에 북부 바렌스로 데려갈 수 있어요"
rows["92:1675589179"]="실종된 페이지, 부실한 장비, 오염된 샘플! 이런 조건에서 어떻게 일할 수 있을까요?"
rows["92:1678979662"]="여기 와서 원하는 포스터를 봐요!"
rows["92:168119451"]="처음엔 무슨 일이 있었지?"
rows["92:1681679228"]="[악마] 레보스 아플 오케 모르단나스 아키미 마즈 나즈테로스!"
rows["92:1686237504"]="밸리의 노래가 벽에 걸려있어요."
rows["92:1690963939"]="하지만 남쪽 민족들에게 가능한 도움을 주십시오. 그들은 실랩 인우아의 챔피언입니다."
rows["92:1695164070"]="내 임무는 알을 보호하는 것. 알에 손대지 못하게 모두 불태워 주마."
