rows["92:6697254"]="잔인한 세이야드는 불타는 군단의 성전이 지닌 교활한 면을 보여 주는 좋은 증거입니다."
rows["92:698338716"]="%s]는 고백한다: 나는 빛을 요청하여 나에게 힘을 주지만, 그것이 정말로 그렇게하는지 확신하지 못한다."
rows["92:708680887"]="타레타의 삶은 그 물결에 걸려있지 "
rows["92:719138493"]="미안해, 내버려두지 못했어."
rows["92:729663111"]="워송 구치의 입구가 당신 앞에 있습니다. 얼라이언스 - 저기요?"
rows["92:730310445"]="그래, 떠나야지... 하지만 그 전에 얼라이언스 놈들에게 날 잊지 못할 선물을 주고 가야겠네!"
rows["92:732047364"]="고객이 선택되면 열린 좌석을 클릭하면 고객은 거기에 앉게 됩니다."
rows["92:775339381"]="아나, 10분 더 쉬면 씻어내야 돼"
rows["92:777000447"]="제 새끼를 놓쳤어요, 대군님"
rows["92:777865907"]="내 새 주인들은 널 처형하기 전에 내 이름을 네 몸에 새겨낼 거야"
rows["92:780979775"]="으음... 그래... 정말 대단한 얘기였어. 곰곰이 생각 좀 해봐야겠군. 고맙네."
rows["92:78217920"]="코바이는 야롱들을 이끌고 우리를 공격하지만 그는 우리의 문제들의 원천이라고 생각하지 않는다."
rows["92:806028198"]="리리, 죄수들을 다시 경비소에 데려가줘요"
rows["92:812932658"]="한때 모가들은 판다리아의 모든 인종을 노예로 삼아 그들의 악의적 의지에 복종시켰습니다."
rows["92:814157900"]="우린 겨우 지지를 잡을 수 있어 모든 군인들이 복무에 출범해야 돼"
rows["92:815803811"]="얼라이언스은 우리의 유아 노동 캠프에 새 달마다 신선한 아기를 출산시켜야 한다고 요구합니다."
rows["92:822519561"]="그 사람은  ⁇ 인입니다. 그는 스스로 치료되기 전에 감염되어 죽었습니다."
rows["92:824681956"]="이제 산그라즈가 다시 내 거야 여기서 찾을 수 있는 유일한 것은 네 자신의 무덤이야"
rows["92:834298992"]="%s 자신의 웃음을 거의 통제할 수 없습니다. 그의 이야기는 자신의 웃음으로 끊임없이 중단됩니다."
rows["92:843798344"]="똥구멍을 닫아, 깃털이신 멍청아! 이 해적들은 널 잘라서 모자를 입고 갈 거야!"
rows["92:846940910"]="너무 감사합니다. 또 한 달 더 내 유연철 냄비에 대한 보증 기간을 연장할 수 있어서 다행입니다."
rows["92:856077317"]="너도 네 목적을 위해 영혼들을 모으는 걸 보군"
rows["92:859577017"]="좋아, 그 정도 실력이면 수석기술자 텔로니쿠스를 상대해 볼만하겠어."
rows["92:863826691"]="알드라시일까지 올라가는 램프가 바로 저쪽에 있습니다."
rows["92:868616226"]="이 장소를 배치하기 위해 얼마나 세웠어요?$B$B그 무라를 훈련에 쓸래요?"
rows["92:879545780"]="읽는다고 뭐가 달라지는지 모르겠다. 케켁은 글 못 읽는데. 헤멧 네싱워리가 그렇게 말한다면, 케켁 해볼 거다."
rows["92:879729646"]="고맙다는 것은 불필요하네, 친구."
rows["92:889674535"]="가로쉬는 모든 무기를 사용 중이야"
rows["92:913237736"]="바리마트라스가 떠나고 있는 동안, 저는 브래고르 대장에게 그의 직무를 수행하도록 임명되었습니다."
rows["92:918629270"]="가자 $p만약 우리가 여기서 유용하게 사용될 수 있다면, 우리는 동맹을 필요로 할 것입니다."
rows["92:920503777"]="갈등과 분쟁은 우리 중 어느 누구도 기억할 수 있는 한 우리의 끊임없는 동반자였습니다."
rows["92:922141503"]="우린 먼 길을 여행하고, 이제 샤도파인은 우리의 물건을 원하지 않는다고 합니다."
rows["92:928501662"]="내가 직접 너희를 상대해야겠구나. 스컬지여, 종교재판관의 무서움을 느껴 보아라!"
rows["92:947441706"]="내가 그 정도에 속아 넘어갈 것 같으냐, 어리석은 놈들! 내게 맞서고자 한다면 내가 있는 곳에서 내 방식대로 싸워야 할 것이다."
rows["92:952011499"]="방금 또 다른 신병 부대를 나그란드로 보냈습니다. 그들을 위해 기도해 주시겠습니까?"
rows["92:956216220"]="당신은 대전강 북쪽에 있는 딥마운틴 광산과 보석 제조를 원해요"
rows["92:964481754"]="이 쓰레기는 끔찍한 마법에 의해 상처받습니다. 우리는 이 큰 상처를 치유하기 위해 최선을 다해야 합니다."
rows["92:9791943"]="내 친구한테 한 용도로... 내 옷에 대해 진실을 말해줘요."
rows["92:987507563"]="<이 부른 악마가 메디브의 규칙에 맞서 싸우며 당신의 영혼을 원하고 있습니다!>"
rows["92:99372230"]="우린 적들을 총으로 죽일 수 있어야지"
rows["92:998286918"]="내가 물어보면, 난 괴물들이 신발을 입는 것 같아. 우리는 도구와 재능이 있어!"
rows["93:1019976439"]="좋은 일이야, 더 많은 트로그들이 표면에 도달하지 못하도록 전하를 발사할 거야"
rows["93:1020342849"]="하무를 죽인 것처럼 네 동료를 죽일 거야"
rows["93:102518652"]="빚을 갚으려 하니까 오늘 갚아줄게 다음엔 좀 더 책임감 있게 해"
rows["93:104540202"]="보시다시피 두려움으로 인도하는 사람들은 권력을 유지하는데, 지배하는 사람들은 용기가 부족합니다."
rows["93:1054027222"]="리디안, 펜타루스 대마법사님과 브란에게 이 방어 설비에 대해 당장 알리세요."
rows["93:1057985318"]="기름이 부족해 뱀을 봐서 괜찮아"
rows["93:1061687266"]="재앙 이후 계속 싸우고 있어 잠시 쉬는 게 좋겠네"
rows["93:1064012234"]="끈질긴 놈들! 주인님 계신 근처도 못 갈 것이다. 병사들아, 저놈들을 해치워라!"
rows["93:106943556"]="다음번엔  ⁇ 은이 내가 직접적으로 당신을 마주하게 해 주길 바래요"
rows["93:1069943483"]="도와줘서 고마워요, 우리가 할 수 있는 모든 것을 해 줄께요"
rows["93:1072614641"]="%s는 마지막 에너지를 근처의 룬스톤에 방출하여 성공적으로 재활성화합니다."
rows["93:1074576217"]="운전하고 싶지만 고아 가부장님이 내가 나이가 들 때까지 마운트를 못 받을 거라고"
rows["93:1077256024"]="죽음 을 기뻐하는 사람 은 아무도 없읍니다. 그러나 우리 는 두려움, 분노, 의심 을 느끼지 말아야 합니다."
rows["93:1083401369"]="왜 큰 돌을 들고 다니야 해? 데이는 새로운 워시프 밑에서 더 적은 일을 하라고 했지! 데이는 돈을 바꾼다고 약속했지!"
rows["93:1095429063"]="어서, 여행 향수를 심히 숨쉬세요. 행운을 빌어 버랩 웨이스타션으로 가세요!"
rows["93:1109366491"]="아무짝에도 쓸모없는 바보들! 우리가 아킨둔을 차지했어야 하는 건데... 쥐새끼처럼 기어오르는 네놈들을 보니 한숨만 절로 나오는구나!"
rows["93:1124853821"]="마직 쿼터에 항상 다크에 있는 아르먼 크롬웰."
rows["93:1132768212"]="일부 사람 들 은 연합 을 전파 할 것 이다. 그러나 연합 은 가장 약한 연결고리 를 깨뜨리는 데 방해 가 됩니까?"
rows["93:1135141978"]="셀라나 대장이 선웰 고원도에 있는 당신의 노력에 도움을 줄 것을 지시했습니다."
rows["93:1141084865"]="단단히 준비하세요! 나가들이 우리가 살아 있다는 걸 알면 곧 다시 공격하려 올 겁니다."
rows["93:114797424"]="사우티드 카로츠는 내가 좋아하는 음식이고"
rows["93:1157622560"]="자연적으로 악성적인 이들은 자신의 급히 만들어진 기술을 사용하는 것을 좋아합니다."
rows["93:1159749018"]="또 하나 내려요, 저 빛줄을 보세요!"
rows["93:1198684855"]="지금 투기장에 다르나서스의 최고 용사이자 노련한 파수꾼인 제일린 이븐송이 들어서고 있습니다!"
rows["93:1244747715"]="남부 던 발다르 참호가 공격받고 있습니다! 저지하지 않으면 얼라이언스에 의해 파괴되고 말 것입니다!"
rows["93:1261425192"]="밀과 물의 조상들이여, 내가 너희를 위한 길을 닦았으니 스톰윈드!"
rows["93:1266292052"]="안녕하세요, 시티 파워, 좋은 이야기를 들려주신 적이 있나요?"
rows["93:1273270431"]="멋진 겨울 베일 축제를 시작해 스모키우드 가시즈의 맛으로 시작해"
rows["93:1282476229"]="괜찮아... 하지만 우리 친구 $p이 여기 완전히 덮여있는 것 같습니다."
rows["93:1302094544"]="좋아, 나 갈게요. 하지만 이번이 마지막 번이야 내가 호드에 침투할 거요!"
rows["93:1302202006"]="오늘은 막 튕기네, 알았어... 잘 알았으니, 기분이 좀 좋을 때 다시 보자고."
rows["93:1311366839"]="<아카네 수호자는 큰 동굴이 발견될 수 있는 하위 도시로 내려가게 됩니다.>"
rows["93:1321660696"]="끝내라! 어서 끝내! 안 그러면 알렉스트라자께 맹세코 다시는 빛을 못 보게 해주마!"
rows["93:1323975201"]="저주에서 벗어나고서 겨울이 닥치자, 나 같은 노련한 오크 수백 명은 절망의 늪에 빠지고 말았지."
rows["93:1338327478"]="[%s가끔은 마법사가 나를 불러달라고 요청합니다."
rows["93:1340713621"]="불! 파괴! 죽음! 내 가슴 속에 검은 불길이 끓고 있다! ...내뿜어야만 해! 우하하!"
