rows["93:1374362499"]="램트래블 탐사원이 다시 해봤어 아이언포지 이 모든 것을 이해할 수 있습니다."
rows["93:1377476886"]="되도록 빨리 빠져나가야겠군. 언데드에게 죽지 않아도 불에 타 죽게 생겼어."
