rows["93:1390400135"]="계속해야 돼 그들의 결단력이 약해졌어 내 힘을 마시고 다시 새롭게 되라"
rows["93:1397170920"]="그림자 엮기 위한 패턴이나 지식을 찾고 있다면, 저는 기꺼이 도와드릴게요."
rows["93:1403393525"]="뇌가 있는 사람이 이미 물을 가져와야 할지도 몰라"
rows["93:1406264101"]="더크문 특별보호구에 또 한 번 들어와서"
rows["93:1407893325"]="에피스 중 에는 10 열 공기 풍선 이나 체크포인트 가 있다. 지금 이 곳 을 지나가고 있습니다."
rows["93:1411031896"]="세상에서 가장 큰 모기건 세상에서 가장 위대한 영웅이건, 너흰 어차피 필멸의 존재야."
rows["93:1415735503"]="내 복도 어때요?$B$B난 고기 조각이야!"
rows["93:1426444050"]="블랙파텀 딥은 잿빛 골짜기 해안에서 조람 스트랜드 북쪽 끝에 발견된다."
rows["93:1429761763"]="만약 당신이 물어봐야 한다면, 당신은 저를 그렇게 부르기에는 충분히 잘 알지 못합니다."
rows["93:14365759"]="네, 네, 네, 그리고 네, 네, 네가 할 것이다."
rows["93:1451274064"]="친구들랑 술도 마시면 좋네요."
rows["93:1455579801"]="여기까지 오다니 너무나 어리석구나. 노스렌드의 얼음 바람이 영혼까지 삼키리라!"
rows["93:146215688"]="듀로탄 님의 아들... 가라드 님과 게야 님의 손자시여... 고개를 숙여 대족장님에게 인사를 드리십시오..."
rows["93:1467606773"]="병사 토르센, 순찰을 마치고 돌아왔습니다. 새로운 보고 사항은 없으며 그쪽 지역은 상당히 조용합니다..."
rows["93:1472555251"]="승부사의 전당의 입구에 걸린 저주가 풀리려는 듯, 카라잔의 전당이 심하게 흔들립니다."
rows["93:148603767"]="이곳 빛의 대성당은 스톰윈드의 영혼 계몽의 중심이랍니다."
rows["93:149136774"]="용이여, 나를 화나게 하는군. 난 아랫마을 주민들처럼 쉽게 겁먹지는 않을 걸세."
rows["93:1495458125"]="이 공학자를 찾아보자, 아마도 이 거시가 제거되지는 못해"
rows["93:14982472"]="미안해, 토테임이 당신의 섬세한 감각을 상하게 했나요?"
rows["93:150299670"]="난 늘 현명한 판단을 내렸지만, 언니는 그러지 않았어. 더는 우릴 파멸로 몰고 가게 두지 않겠어!"
rows["93:1520270390"]="로키, 나한테 무슨 말을 했나?"
rows["93:1522449210"]="어떻게 대안 9을 관세로 데려갈 수 있을까요?"
rows["93:1532286865"]="밀과 흙의 조상들이여, 내가 너희를 위한 길을 닦았으니 오그리마!"
rows["93:1547759868"]="가짜 마스터는 어디야?"
rows["93:1562171882"]="이 시점에서, 저는 누군가에게 수단을 조사하도록 불러서 숨겨진 방을 찾아낼 것입니다."
rows["93:1570664470"]="아후나이의 도끼가 드라카리의 종말이 될 것입니다.$B$B내 도끼를 넘어서면 다 챙겨라!"
rows["93:1582299604"]="자유클 여성들은 싸움을 할 수 없다고 들었습니다."
rows["93:1593013763"]="이 모가들은 과거에서 겪은 것과는 전혀 다른 싸움을 하고 있습니다."
rows["93:159326947"]="물론, 아무 것도 생각하지 마 그리고 당신은 나에게 돈을 갚을 거란 건도 듣지 않을거야!"
rows["93:1594284131"]="이런 날 야외에서 나서는 게 싫지만 의무는 나를 묶어 놓습니다"
rows["93:1603014053"]="환영합니다 $p아들에게 도움을 준 걸 잊지 않을 거야"
rows["93:1607493073"]="저는 판다리아에 새로운 여행자의 방식을 따르고 있습니다. \"파우더가 건조하고 맥주가 차가워지세요!!\""
rows["93:1642488955"]="저한테 맞서 싸우는 건 몇 명뿐이야"
rows["93:1649268520"]="지구 반지의 어느 누구도 의심했던 것보다 훨씬 더 큰 문제로 대두하고 있는 것 같습니다."
rows["93:1651047220"]="내 전기가 오고 곧 도착할 겁니다$b$b그들이 돌아왔을 때 다시 말해주세요"
rows["93:1655175535"]="용 영혼은 다시 안전해져요, 이 세상이 무너지기 전에 시간 포털로 빨리 들어가세요!"
rows["93:1659610838"]="다시 한번 고마워요. 도린 하사관도 이번 주에 보충할 정찰병이 하나 줄었다니 좋아하겠군요."
rows["93:1663289362"]="서머스 리스트에서 상품 판매가 있는 여자 한 명 알고 있어"
rows["93:1685552251"]="그를 내버려두는 건 이제 널 짐승과 분리시킬 유일한 거야"
rows["93:1689937601"]="목소리 좀 낮아줘 타란이 널 지휘관으로 선택하지 않았다는 건 놀라운 일이 아니지"
rows["93:1693204967"]="이 치명적인 상자가 극도의 온도 변화를 얼마나 잘 처리할 수 있는지 알아야 합니다"
rows["93:1713981446"]="여기 사람들은 당신을 얘기하고 있어 친구"
rows["93:1716260661"]="하지만 왜? 용은 크고 강하다. 엘프 여자 약하다. 케켁은 용의 여왕 진짜 모습 보고 싶다."
rows["93:1720657178"]="들어가려면, 지역 내 일부 마티드 지도자들의 특별히 조율된 크리스탈이 필요합니다."
rows["93:1722701613"]="테로니우스는 전투에 대한 당신의 기술에 대해 많이 말해줬어요"
rows["93:1723400439"]="드래곤 플라이트의 친구이자 동맹자 여러분, 여기 오신 것을 환영합니다."
rows["93:1736956550"]="당신은 힘에 대해 아무것도 몰라요. 당신은 절망에 빠진 동맹에게 붙어있지만, 그들은 당신을 구할 수 없습니다."
rows["93:1739279480"]="비크, 어서 가봐, 큰 텐타클이야. 도넬리는 널 안전하게 지켜줄거야!"
rows["93:17497725"]="죽음의 날개는 당신들의 모든 순서를 멸망시킬 것이고, 오늘 저는 그의 칼이 될 것입니다."
rows["93:175414622"]="이봐, 노인 틸에 대한 이야기를 들어봤어?"
rows["93:1756445417"]="알렉스스트라사 (Alexstrasza) 는 이미 죽음의 날개와 연계되어 있어!"
rows["93:1763207267"]="제물을 다른 거시 안에 주인의 피와 육신으로 가져오세요."
rows["93:1763429230"]="끝은 빨리 다가오고 있습니다. 에라니쿠스에 항복하고 영원한 고통이 아끼지십시오."
rows["93:1769766706"]="전 전사 훈련을 받았지만, 마법에 더 능숙하다는 것은 아무도 모른다."
rows["93:1771483382"]="발하라스를 잘 못하면 요툰하임에서 다른 전투가 있습니다."
rows["93:1775111060"]="그럼 알갈론은 어떤 식으로 진단 결과를 내지? 우린 희망이 없는 거냐?"
rows["93:177528696"]="%s은 아카마의 주의가 바가트의 마지막 말로 이동하면서 잠에 미끄러진다."
rows["93:1778223506"]="희망이 없다는 걸 알아듣지? 이미 죽음 날개가 올라왔어. 네 세상은 멸망당해"
rows["93:1779320834"]="지금보다 더 나아지기 위해 Nat Pagle를 Dustwallow Marsh에서 찾아야 할 거야"
rows["93:1784443901"]="트롤, 혼자 가세요. 아마 이 늙은 샤만은 그 농부들에게 한 두 가지를 가르쳐 줄 수 있을 겁니다."
rows["93:178483255"]="내 신... 이 모든 것은 만년 동안 판다리아를 괴롭힌 끔찍한 존재의 남은 것입니다."
rows["93:1786124544"]="또한 무대에 들어오는: 대부적인 마스터 붐 붐, 다이노미트 던지는 원숭이 수도원!"
rows["93:1805191728"]=" ⁇ 의 요소들은 너무 혼란스럽다! 지금 결합하면 어떻게 될지 모르겠어요!"
rows["93:1808123626"]="폭풍우가 오자, 레지옹의 주인에게 배신하는 사람들에게 무슨 일이 일어나는지 보여드리겠습니다!"
rows["93:1808270877"]="이 릴리저는 반복복용 실린더가어야지?"
rows["93:1832964278"]="수도원에 할 일이 너무 많아서 그럴 거예요. 그래도 지금쯤은 돌아와야 할 시간인데..."
rows["93:1855670317"]="안녕하세요, 환영합니다. 나는 미소를 잘하지 않지만 나를 신뢰하십시오. 나는 당신을 위해 기쁘게합니다."
rows["93:1862498506"]="챔피언, 다시 한 번 당신은 호드 또 다시, 난 당신에게 빚을 지고 있습니다."
rows["93:1923721993"]="마법사를 배우고 싶다면 아포테카리움의 내부 반지에서 라비니아 크로웨를 찾아라"
rows["93:192888270"]="난 이 쓰레기 때문에 가입하지 않았어. 전 다시 메카토르크에 가서  ⁇ 메레건을 되찾아 줄 수 있었을 거야!"
rows["93:1934042619"]="사우스윈드 마을 근처에 뭔가 움직이고 있어요 모래 벌레 중 하나예요"
rows["93:1939834627"]="그럼 역사에 대한 당신의 지식을 시험해 보겠습니다."
rows["93:1940978621"]="넌 우리를 과소평가했어,  ⁇  부. 우린 널 이 곳에서 없애버렸어."
rows["93:1956253464"]="내 크기가 널 따라다니지 말아"
rows["93:1960972422"]="우린 작은 마을이야  ⁇ 왕의 세력을 물리치려면 어떻게 해야 돼?"
rows["93:1976105055"]="저는 돌을 뛰어넘는 걸 좋아할 것 같습니다."
rows["93:197624857"]="고구려로 돌아가는 걸 찾고 있어? 티리스팔 숲 클라우드 키서에서 스타일리쉬한"
rows["93:1978657548"]="제가 뭐라고 반박하겠습니까? 고블린과 거래를 트기 전에는 지갑에 쇠 자물쇠부터 다는 게 상책인데요."
rows["93:1979574290"]="아직 무슨 내용이 있는지 모르겠지만, 패트 나글과 마이클 배쿠스는 먼저 이 문제를 논의해야 합니다."
rows["93:1980609929"]="상공이 우리를 떠나기 전에 널 항구로 데려가야 돼!"
rows["93:1987471929"]="누가 널 여기 보내니? 아직 내 명령에 준비가 안 됐어. 준비가 되면 알려줄게."
rows["93:1998940554"]="첫 번째 호드 경비탑이 무너졌다! 세 개를 모두 무너뜨리면 적은 금세 퇴각할 것이다!"
rows["93:2016121471"]="이하갈루크 크래그로 가세요. 제가 도착하면 여러분의 환상의 두 번째 반을 적용하겠습니다."
rows["93:2018894679"]="스미머리지, 잘 알고 있어요. 프로스트맨 트롤들은 눈빛에 휩싸인 메사 위에 번식하고"
rows["93:2020920093"]="가로쉬, 여기선 자제해주기 바라네. 보랏빛 성채 때와 같은 상황을 또 만들고 싶진 않네."
rows["93:2027020552"]="저는 노스렌드, 크롬가르에서 아주 오랜 시간을 보냈습니다. 그 기간 동안 호드에 대해 많은 것을 배웠어요."
rows["93:2031115038"]="한심하기 짝이 없는 네 도전 따위는 누구 하나 알아주지 않고 끝났다. 이제 네 목숨을 빼앗기 전에 좀 가지고 놀아야겠다."
rows["93:2056944423"]="뒷좌석에 앉자, 우린 여기서 나가야 돼"
rows["93:2067252758"]="우리 가족들과 함께 어들러스에서 신선한 물고기를 가져오고 있어요"
rows["93:2069153801"]="물 자체가 올라가서 그들을 대적하지만 왜?"
rows["93:2070103773"]="네 잘못이라고 말하지 않겠어, 타렌어 하지만 그 때문에 기드윈을 구하지 말아라"
rows["93:2076361429"]="내가 카스타넛을 먹으면, 불을 뜨게 해 줄게."
rows["93:2086180651"]="로켄과 무쇠 드워프들이 토석인을 내쫓고 울두아르를 차지했습니다."
rows["93:2095331403"]="부츠를 만지지 마, 경찰이 증거를 수집할 때까지 기다린다"
rows["93:2115626674"]="우린 오래전부터 당신의 귀환을 갈망해 왔어요!"
rows["93:2117213338"]="아, 안세크와의 지혜를 찾아라. 썬더 블러프 무기를 가져"
rows["93:2120673971"]="이 포세이큰 그들은 우리가 약하고, 부서진 사람들로 생각하며, 겁먹은 개처럼 굴러올 것이라고 생각합니다."
rows["93:2124398466"]="우리 손님께 샤트라스를 구경시켜 드려라. 고난의 거리에 가면 소매치기를 조심하고."
rows["93:21259292"]="이건 모욕이야! 무례하다고! 유서 깊은 드워프의 전통 행사에 우리를 참가하지 못하게 하다니!"
rows["93:2134216973"]="이 후, 나랑 몇몇 소년들은 댄싱 뱀 인을 방문해서 맥주 한 잔을 먹으러 가죠."
rows["93:2134814965"]="얼라이언스와 호드의 투사여! 은빛십자군의 깃발 아래 모인 그대들을 환영한다."
rows["93:21713448"]="어떻게 괴물들이 이런 짐승들에게 팩을 확보할 수 있을까요?"
rows["93:218260886"]="<밀런 그리폰 라이더는 가만히 있고, 눈을 앞으로  ⁇ 고, 당신의 존재를 인정하지 않는다.>"
rows["93:247190111"]="몇 가지 전투장 중에서 선택할 수 있습니다. 어느 전투장에게 보내야 할까요?"
rows["93:248402771"]="강아지들이 자주 이곳을 공격해 버그들을 겁에 질려서"
rows["93:256336488"]="내가 공격 명령을 내릴 때 내 군대의 밴에 있을 것이라고 호가르에게 말해주세요"
rows["93:258909013"]="그럼 제가 이 껍질을 가지고 있다고 가정해보죠. 더 이상 무엇을 필요로 하고 실제로 무엇을 만들 수 있을까요?"
rows["93:267215617"]="세상을 돌아다니며 자신의 이야기를 쓰는 것보다 더 큰 기쁨은 없습니다.$B$B그것은 방황자의 길이다."
rows["93:274985920"]="%s는 그녀의 남편을  ⁇ 어 들며 농장에서 계속되는 불길한 존재에 눈을 뜨게 됩니다."
rows["93:281189568"]=" ⁇ 진 수, 우리는 리우랑의 후손이야 네 고통을 느끼고 도와주고 싶어"
rows["93:283862229"]="정말 도와줄 수 있었으면 좋겠지만, 못해요 쿠르드란이 직접 명령을 내렸어요"
rows["93:285134243"]="그 다음에는 선리버들이 그녀의 신뢰를 배신하고 바로 그녀의 도시에서 벨을 통해 포털을 열게 될 것입니다!"
rows["93:306050672"]="북부 던 발다르 참호가 공격받고 있습니다! 저지하지 않으면 얼라이언스에 의해 파괴되고 말 것입니다.!"
rows["93:323763799"]="어서 와라, 친구들. 너희 몸이 내 새끼를 배불리고 너희 영혼이 내 힘이 되리라!"
rows["93:330295186"]="새로운 무기를 사용하도록 훈련받기 위해 온거니?"
rows["93:34145748"]="챔피언, 안두인과 함께 오늘 워시프를 좌절시켰고 얼라이언스에서 중요한 승리를 거뒀어."
rows["93:347628736"]="우린 다크스피어처럼 체인을 잘 안 입는 사람이 아냐 곧 힘들게 배울 거야"
rows["93:353195546"]="더 설득할 필요 없어, 날 필요로 한다면"
rows["93:355334390"]="우리의 손실에도 불구하고 왕은 나가 장군이 패배했다는 것을 알고 기뻐할 것입니다."
rows["93:356628944"]="당신의 왕은 그의 무리를 불러서 말의 진정한 의미에서 얼라이언스을 모으고 있습니다."
