rows["93:68203878"]="우리가 싸운다면, 노스렌드에 둘로 나뉘어진 병력을 리치 왕이 손쉽게 무너뜨릴 것이오."
rows["93:68995896"]="이렇게 빨리 날 데리러 오면 어떡하나! 난 아직 약하단 말이다... 이건 뭐야! 누구지... 상관없겠지! 죽어!"
