rows["94:1277470442"]="|TInterface\\Icons\\inv_misc_fork&knife.blp:20|t|cFFFF0000|Hspell:146448|h[급식을 기다리는]|h|r"
rows["94:128165994"]="이 불 신자들은 성전을 침입하고 비밀을 훔치려고 합니다"
