rows["94:1356448565"]="대신, 그러한 비상 상황 에 대비하여 배치 된 여러 갑판에 설치된 화살기 공을 찾아보세요."
rows["94:1361432969"]="날 실망시키지 마라, 산레인. 이 멍청이의 머리를 손에 넣기 전에는 얼음왕관으로 돌아오지 마라."
rows["94:1362447885"]="그만두십시오, 마이클. 지금의 무서운 상황만으로도 장사가 충분히 타격을 받고 있습니다. 한 푼이라도 아끼면 됩니다."
