rows["94:266921686"]="단지 바라보았다는 이유로 그대가 먼저 날 나무라지 않았소. 어쨌든 난 아직 티란데와의 접견을 기다리고 있소."
rows["94:281434137"]="그레고리, 죄수들을 다시 경비소에 데려가서 제대로 처리해 줄 수 있어"
