rows["94:296240267"]="이 곳은 고고학자의 꿈입니다!$b$b제대로 된 발굴을 할 시간이 있었으면 좋겠어요."
rows["94:29679479"]="아니, 오늘 맛검사가 없을거야 누가 훔친 곡물을 되찾기 위해 도와주지 않는 한"
rows["94:303088146"]="이 말을 무시하고 물에 뛰어들지 않으면 무슨 일이 벌어질지 꽤 궁금하군."
rows["94:311896372"]="5개의 아르헨트 타워를 지고 있는데 대부분 정비, 유지보수 그리고 약간의 마법 작업이 있습니다"
rows["94:31621038"]="다른 날엔 이런 짓을 하지 않겠지만 목마른 상태이고 혼자 술을 마시는 것도 싫어$B$B바닥이 올라와!"
