rows["94:327150626"]="좋아요, 여기부터는 혼자 갈 수 있을 것 같군요. 저를 그 무서운 곳에서 빼내줘서 정말 고마워요!"
rows["94:338510717"]="네가 아직 살아 있고 내 손들이 네 꼬마 목에 단단히 잡히지 않았기 때문입니다."
rows["94:338999666"]="...그 스쿠르비드 개는 두 개의 톱니 다리, 왼손에 갈고리, 유리 눈 두 개와 목조 코를 가지고 있었다!"
rows["94:342023167"]="그들은 작은 소아처럼 소아들을 살려 먹지 않고$B$B난 나가를 싫어!"
rows["94:34234012"]="내 보조들이 너무 많은 걸 증명해줬어"
rows["94:348736509"]="수영을 하고 싶었지?"
rows["94:364679190"]="램스타인에게 돌아가서 또 다른 양을 구해줘"
rows["94:365415413"]="레이제크 맘에 들어! 보호모 때문에 우리 아가들도 겁먹는다면, 겁쟁이 날름이들은 어떻게 나올지 보고 싶어 못 견디겠어!"
rows["94:374246892"]="모아그 종족 출신으로 불타는 군단에게 징병되었으며 이 전사들은 불타는 군단의 고위 계층의 사병입니다."
rows["94:388696216"]="난 물품이 너무 부족해 왜 저 망할 괴물이 그렇게 오래 걸리는 거야?"
rows["94:393152651"]="집중하거나 휴식을 취할 수 있지만 무엇보다도 중심에 머물러 있어야 합니다."
