rows["94:479096942"]="이 임무는 내가 아닌 다른 사람의 손에 당신의 수리 작업을 맡기기에는 너무 중요합니다."
rows["94:480544533"]="내 생각엔 괜찮아 보이는데 다음번엔 거대 살인 크로코딜에 대해 경고해 줄 수도 있겠지"
