rows["94:52001226"]="제가 탈라시안어에 능통하다는 걸 알면 라린나님께서 즐거우시겠군요. 지금하신 답례 말씀에 담긴 호의는 잊지 않겠습니다."
rows["94:535945822"]="내가 정신을 차려서 스라이어가 이렇게 섬세한 작전에 도움을 주었을 거야"
