rows["94:592456714"]="또 다른 마녀? 지난번의 사건 이후, 우리가 당신을 본 직후 죽이지 않았으면 기뻐해야 합니다."
rows["94:599339661"]="날 죽이려고 생각했어, 미세한 인간 이 작은 괴물은 네 비참한 인종보다 더 용감해"
