rows["94:611297450"]="친구들, 오늘 우리는 이 세상을 치유하기 위해 모였습니다. 우리가 그렇게 많은 희생을 해왔죠."
rows["94:611930219"]="오래전 그대들은 우리 동료였습니다. 우리는 악마에게 몸을 바쳤고 그대들을 잊었습니다."
