rows["94:637019036"]="하지만 우리는 전쟁 기계에 먹이를 줘야 합니다. 돌, 나무, 기름, 육류는"
rows["94:654894537"]="\"우리 모두는 어린아이처럼 되어야 합니다. 세상 은 우리 의 장로 이며, 우리에게 배울 많은 것 이 있다\"."
rows["94:66849167"]="매혹적인데, 이런 이야기를 들어본 적 없어. 모고들은 비밀을 잘 숨긴다."
rows["94:67428634"]="언젠가 우리의 고대 지식을 개선하기를 희망합니다."
rows["94:677099346"]="멋진 파티 앙상블을 풀고 멋있는 색채, 신형 옷과 빛나는 블링을 착용하세요!"
