rows["94:719206482"]="이 타운카를 보호하고 우리가 제공할 수 있는 작은 위로를 제공하는 것이 우리의 의무입니다."
rows["94:725521205"]="<아카네 수호자는 계단 너머의 장소로 향하고, 숙소와 인근 우편 상자를 향해 움직인다.>"
rows["94:730720087"]="형제 자매 여러분, 우리는 단결을 유지해야 합니다. 리치 왕는 결코 분열된 세계에 넘어가지 않을 것입니다!"
rows["94:732192918"]="힘의 계곡으로 가서 천문 남쪽의 오그리마 은행을 찾아보세요."
rows["94:741695205"]="그런데 갑자기 키가 100미터 정도 되는 악마가 나타나 그 거대한 나무를 오르기 시작하는 겁니다."
rows["94:743233859"]="이 식물은 다르나서스아마 살인자는 신발을 들고 여기까지 끌고 올랐겠죠"
rows["94:743786744"]="축하하네, 용사들이여. 예정된 시험이든 뜻밖의 시험이든, 그대들은 모두 이겨냈군."
rows["94:753957533"]="그렇게 할 경우, 주문을 걸기 전에 제대로 고정하지 않으면 흐름의 구조가 해체되지 않을까요?"
rows["94:755859325"]="래이더, 순위에 합시다. 코프펀의 신호에 따라 이 겁쟁이 개들을 공격하고 마쳐라!\010"
rows["94:763097267"]="아즈하라에 새로운 집이 있고 빌그워터 카르텔은 호드의 일부가 될 것입니다!"
rows["94:773251674"]="내가 연구로 묻혀 있는 동안, 당신은 라셔에게 세상의 길을 가르쳐야 합니다."
rows["94:782020786"]="...그리고 우리의 주인에게 헌신적인 종으로서, 당신은 그리고 샌드푸리 부족은 정의롭게 보상됩니다!"
