rows["94:868853245"]="언제나 그렇듯이 타이밍이 완벽해, 영웅."
rows["94:877085668"]="우리 병력을 조각낸 아서스는 가장 강력한 이들을 산레인으로 받아들여 자신을 섬기게 했다."
