rows["94:924549145"]="여기서는 다크크레스트와 블러드스케일 부족의 나가 지도자들에게 보상 공지사항이 나열되어 있습니다."
rows["94:925466702"]="사랑해, 안비나! 내 목소리를 들어줘! 날 위해서라도 제발 돌아와! 오직 너만이 태양샘을 정화할 수 있어!"
rows["94:936843735"]="시로나스가 죽었다! 드... 드디어 모든 게 끝났다는 것이 믿을 수가 없군! 해냈단 말이오! 당신이 블러드 엘프 녀석들과 시로나스를 해치웠소!"
rows["94:944907470"]="보군, 여자들이 골라카 온천의 황화한 물에서 지갑을 잃었습니다."
rows["94:945818520"]="제가 중요한 일을 중간에 하고 있었기에 방해가 좋은 이유가 있었으면 좋겠습니다."
rows["94:95271368"]="우리 마법사들은 보석공예가 있는 크리스탈 홀에 있습니다."
rows["94:958880202"]="기억하세요. 담당자를 괴롭히거나 채널을 도배하면 계정이 추방되거나 정지될 수 있으며, 더 심한 제재를 받을 수도 있습니다."
rows["94:962663846"]="나는... 삼키고, 휩쓸고, 압도하고, 파괴하리라! 강력한 바다의 분노에 굴복하라!"
rows["94:973191378"]="내가 바쁘다는 걸 알 수 없지?"
rows["94:975137696"]="어떻게 이런 일이 벌어질 수 있는지 모르겠다만, 넌 이스칼더를 심판해야 한다. 잠깐... 뭐지?"
rows["94:997014698"]="그 이상한 광석의 비밀을 풀 수 있을지 모르겠네요. 쓸모가 있긴 있을 텐데 말이지요!"
rows["95:1022382700"]="황후는 이 무리를 강제로 몰아넣고 우리 땅을 파괴할 것입니다.$B$B비용이 너무 비싸죠."
rows["95:1032606727"]="그들의 자신의 장치에 남겨, 호드 당신들의 땅을 덮치겠소"
rows["95:1038846967"]="왜 다른 기계를 사용하니까?"
rows["95:1050103611"]="전투가 얼마나 좋을까요? 우리 훌륭한 전투원들은 Chagan에 야롱올리안 바베크를 제공했습니다."
rows["95:1069599719"]="확실하지 않네, 캐리아 헤이스팅스한테 물어봐요.7."
rows["95:1073208949"]="워치퍼 모어고르는 드래곤마우를 다시 위대하게 만들 거야!$B$B우리는 당신의 비참한 호드에 필요 없습니다."
rows["95:1097350895"]="우리 아름다운 도시의 사제들은 선푸리 스파이어 안에 있습니다."
rows["95:1106131345"]="우린 곧 캠프를 벌이고, 먼저 이 어둠을 이용해 탐사할 거야"
rows["95:1109554397"]="그래, 맞아! 그 주문... 파멸의 주문... 자네의 스승이었던 어둠의 존재가 사용했던 그 주문!"
rows["95:1116436546"]="이제 우리의 힘은 용 영혼 안에 있습니다."
rows["95:1117031528"]="드디어... 끝났군, 대드루이드 스태그헬름이여. 비록 엄청난 희생이 있었지만 우리의 승리요."
rows["95:1126883740"]="안녕하세요. 저는 여러분의 대화를 듣지 않을 수 없었습니다. 좀 도와드릴게요."
rows["95:1143711334"]="처량한 녀석들. 감히 일리단 님의 사원을 공격하려 했느냐? 좋다, 네 무덤으로 만들어주마!"
rows["95:1150242725"]="그리고, 파괴할 수 없는 구리 무기로 무장한 너희 무르락들은 막히지 않을 거야!"
rows["95:1175676866"]="우린 여기서 놀아야 하지만 난 우리가 너무 많은 곤경에 빠지지 않고 돌아다니는 걸 확신합니다"
rows["95:1178069834"]="오, 내가 총을 가져와 다시 술을 마시면 방해한다면 난 당신을 쏴버릴거야!"
rows["95:1182921917"]="필사자의 함정에 속지 말고 내 힘으로 목욕하라"
rows["95:1203261963"]="다크스피어 부족의 전사들, 우리의 지도자 위대한 볼진은 에코 섬을 되찾으려 준비하고 있습니다."
rows["95:1221623234"]="이 메모들은 끔찍하게 정리되어 있어 아루갈이 똑똑한 사람인지 아니면 바보인지 알 수 없다"
rows["95:1221658288"]="세히 라가 스피릿 라이즈에서 만나게 될 겁니다."
rows["95:1234695531"]="우리 가족들은 혼자 캠프로 돌아갈 거야 나중에 나한테 말 좀 해줘"
rows["95:1241909236"]="물론 사랑과 행복은 잊었어"
rows["95:1244584195"]="우리가 해냈소. 테렌디스를 찾아 우리가 무사하다는 사실을 알려 줘야 한다는 걸 잊지 마시오. 다시 한번 고맙소."
rows["95:1265343059"]="자녀들아, 제발 자행하라! 그렇게 계속 한다면 아무도 너희를 입양하기를 원하지 않을 것이다."
rows["95:1269333533"]="아즈하리트 무기를 파괴했어"
rows["95:1281864832"]="괜찮아, 여기 몇 조각을 가져가면 상관없어"
rows["95:1285749435"]="새 동맹들이 우리와 함께 해왔다고 들었어요"
rows["95:1287810855"]="해머가 착륙할 때, 더 많은  ⁇ 은 철경기자 프레임에서 벗어나고 그 속도는 빨라진다."
rows["95:131443932"]="안타깝게도, 리치 왕을 무찌를 방법은 하나뿐이라네. 그 존재가 생겨난 곳에서 쓰러뜨려야 하지."
rows["95:1325509830"]="책들을 더 잘 정리하기 위해 어떤 표기 시스템을 가지고 있는 데우리와 얘기해야 합니다."
rows["95:1326912917"]="미안하군요, 친구. 자, 여기 있어요. 이 정도면 절 구하는 데 쓰신 비용이 충당되겠죠?"
rows["95:1340637091"]="볼진은 옛날 친구였어, 우리의 길은 갈라지지 않은 지 오래됐습니다."
rows["95:1341629678"]="이제 너희 놈들 차례다! 이 라그나로스의 힘을 찾으러 왔다 했으니 내 몸소 보여주리라!"
rows["95:1345262991"]="해녀가 여기 있어, 내가 알아듣고 있어."
rows["95:1362771248"]="이 트로프가 용아귀 부족원처럼 날 수 있는 법을 보여주도록 하지요... 그리고 당신은 쓸모없는 친구가 어떻게 죽게 되는지 이 트로프에게 보여줄 것이고 말이죠."
rows["95:137943856"]="진주와 친구가 되세요. 임무가 끝나기 전에 필요할 수도 있습니다."
rows["95:1381803382"]="무슨 속임수를 시도하는지 모르겠지만, 난 여기에 참여하고 싶지 않아!"
rows["95:1387112772"]=" 돌고래들이 마지막 배포를 한 것 같군"
rows["95:1389761251"]="우리가 널 잡았다고 두려워했지만 포털 의식에서 벗어나지 못하겠지"
rows["95:1404441555"]="<타이린의 시선은 빈색이네. 보드라시일의 부패를 깨끗하게 하는 것은 드루이드에게 피해를 입혔다.>"
rows["95:1409742292"]="네싱워리는 계속하면 파산할 거야"
rows["95:1425242075"]="이 모든 것은 세계 기둥의 한 조각을 위해서야?"
rows["95:1428001171"]="< 부드는 그의  ⁇ 에 뒤돌아 돌고, 트롤 연설처럼 들리는 것을  ⁇ 고 있습니다. >"
rows["95:1455390830"]="마지막으로, 내 사장에게 용서해줘요. 당신이 그를 때려보고 있는 걸 알 수 있거든요."
rows["95:1460491698"]="빨리 이리 와, 둘 다 행복해"
rows["95:1480565743"]="네가 날 이길 수 있어, 계속하고 싶다면 스노우드리프 마스터를 도조에서 찾아라"
rows["95:1507475779"]="자네가 영광이 될거야, 우리 작전을 보여준 첫 번째 마스터의 희망이야"
rows["95:150759276"]="난 엉망이 됐어요, 지금 좀 바빠요$b$b어떻게 도와드릴 수 있을까요?"
rows["95:1508717784"]="내 친구, 어제 밤 두 마리 닭이 사라졌어"
rows["95:1520027320"]="제 이해로, 얼라이언스의 사람들은 아이언포지년에 이 겨울 베일을 기념합니다."
rows["95:1529352481"]="한 척후병이 토르 모단에서 당신의 일지를 발견했습니다. 이후로 호드는 계속 당신을 찾고 있었지요."
rows["95:1529808674"]="괜히 놀란 척하지 말게. 자네의 그 주술사 친구말이야, 눈이 참 매섭더군. 개구리 눈치곤 말이야."
rows["95:156342596"]="전 그의 대주님께 중요한 일을 하고 있습니다.$b$b\"알아야 할 것\"은 사업입니다. 그리고 당신은 알 필요가 없습니다!"
rows["95:1567018113"]="노인 경로 너머에는 줄기 나무가 있습니다. 오직 가치 있는 사람들이만 들어갈 수 있는 신성한 장소입니다."
rows["95:1567502195"]="괴물이 왔을 때, 샤도파인은 너무 심각해져서 \"샤\"라고 계속 말했어요"
rows["95:1569110044"]="새트라스 신인, 나중에 찾아와"
rows["95:1579701677"]="당신과 당신의 괴물들의 도움이 필요해요 천개의 바늘이 파괴됐습니다!"
rows["95:1594257418"]="그러면 일련의 마법이 양의 극성을 가진 에너지로 연쇄 반응을 일으키게 될 거예요."
rows["95:1597799063"]="지난 시즌에 벌어들인 작은 부로 인해 이 멋진 새로운 카메라를 메일 주문할 수 있었습니다!"
rows["95:1599049821"]="볼진은 살아남았지만 여전히 지옥의 배신을 기억하고 있어"
rows["95:1601205831"]="오늘 정말 좋은 날이야, 안 그래? 오늘이 끝나기 전에 불꽃놀이를 좀 볼 수 있기를 바랍니다."
rows["95:1625036141"]="아내가 우리를 이리로 데려왔다는 것을 감사하지만 아이를 낳기 위해 나쁜 시간을 선택했습니다."
rows["95:1627697899"]="난 제 스쿨 오브 아카네 마직 (Arcane Magic Schools) - 마스터링 부문에서 실종됐어요"
rows["95:162915067"]="이 전쟁에서 승리하는 방법은 이렇습니다."
rows["95:1630836077"]="그렇습니다. 제1관리자 로켄의 활동 정지 접수와 동시에 이 신호가 활성화됩니다."
rows["95:163746101"]="잘 싸워주셨습니다. 이제 북쪽에 있는 그대 쪽 오크 전초기지로 가서 대군주 보르고로크 님께 우리가 성공했다고 알려주십시오."
rows["95:1638797846"]="언더시티에서는 역병 연구가 꽤 진척됐었지. 그런데 갑자기 우리가 만든 변종이 실험하는 족족 실패하지 뭔가!"
rows["95:1638909236"]="콜로스의 힘의 비밀은 과학의 모든 혁신을 이끌어 낼 수 있습니다!"
rows["95:1644833032"]=" ⁇ 이 붙어있는 스프링 로드 펌퍼, 음식을 처리하기 위해"
rows["95:1658898400"]="난 이 무기를 좋은 목표에 맞게 발사할 때까지 기다렸어 탄약을 쓸 수 있어"
rows["95:1659851872"]="사방에 도적들이 깔려 있네. 우리, 백성의 민병대는 반드시 이 땅을 농부들의 손에 되돌려 주어야 하네."
rows["95:1664607248"]="나무에서 자라고 있다고 생각하니?$B$B이런 식으로 일할 수 없어!"
rows["95:1669777534"]="전 한때 제왕후 셰크지어의 가장 소중한 왕실의 화학자였고,"
rows["95:1696466786"]="신비한 화석이 없는데, 그린힐스 오브 스트랭글스톤의 내 복사본은 정말 좋은 책이야"
rows["95:1699023552"]="다른 구석에는 무서운 눈들이 둥글고 있잖아"
rows["95:1723977533"]="풍수호는 이 일을 할 수 없어 그의 재능은 다른 곳에 필요해"
rows["95:1727413200"]="자기 자신이 보스가 되는 게 좋네!$B$B샌드위치에 몇 잔 구울 수 있어?"
rows["95:1750772733"]="강도의 계곡 한가운데에 있는 오그리마 은행 밖에서 하나 발견할 겁니다."
rows["95:175226108"]="피곤한 여행자, 오랜 길을 걸었으니 여기 온크와 캠프에서 휴식을 취할 수 있기를 바랍니다."
rows["95:1760283676"]="난 치유를 배우고 있어요. 문제는 당신이 치유되기 전에 상처받아야 한다는 겁니다."
rows["95:1768638501"]="승려의 훈련은 결코 멈추지 않습니다. 신체와 정신으로 더 높은 단계가 항상 있습니다."
rows["95:1771049608"]="오늘 여기 있을 꿈이 있었지, 이번이야!"
rows["95:1774772272"]="우리 군대의 대부분은 이리lidan에 집중하고 있습니다. 이 땅을 깨끗하게 하는 일은 당신들 몫입니다."
rows["95:177679113"]="이  ⁇ 은 목사가 목욕을 청소할 줄 알았어?"
rows["95:1776799232"]="실리티드들은 치명적이지만 키라지 주왕과 비교하면 소아한 존재입니다."
rows["95:1787907744"]="내게 너무 많은 걸 바라는군. 야만스러운 놈들의 자제력 따위를 믿고 구경이나 하라니 말이오."
rows["95:180176125"]="당신은 이 땅을 계속 재배할 정도로 거저했었는데 경험이 많지 않았죠."
rows["95:1803295936"]="운전수 양반, 당신이 이 지옥에서 마을 사람들을 아주 쉽게 구해냈다던데, 그게 사실인가요?"
rows["95:1805828906"]="고맙소이다, 가로쉬. 대모님을 뵙고 난 후에 그대와 의논할 일이 아주 많소이다."
rows["95:1815907753"]="썬더 블러프 은행의 남쪽에 있는 건물에서 인스키퍼 팔라를 찾아보세요."
rows["95:1819973319"]="엄호해 줘서 고맙소! 우린 지원 병력이 도착할 때까지 관문에서 대기하겠소."
rows["95:1820624828"]="피조물은 하급 존재들과 대화하도록 승인되지 않았습니다. 하급 존재들은 생산량을 두 배로 높여야 합니다."
rows["95:1825533054"]="작은 괴물 건물 위에 로데론- 가 언더시티 그리고 거기 가"
rows["95:1842968008"]="이건 그냥 무사히 보이는 것 같지만, 그 침대도 편안해 보이네."
rows["95:1843608234"]="내 적들을 보기 위해 눈은 필요없어 네 무리한 발자국과 불쾌한 냄새가 너를 몰아넣는 거야"
rows["95:1851967737"]="[%s저는 가끔은 제 마운트를 이용해 아주 짧은 거리를 여행합니다."
rows["95:1856143105"]="안녕하세요 여행자, 전 아다일이 보내신 것인데"
rows["95:185829824"]="괜찮아, 아르투라,  ⁇ 은 냄새가 없어서 우리가 여기 있다는 걸 알 수 없을 것 같아"
rows["95:1861818831"]="바다에서 승륙팀을 보내요, 너희 중 한 명이 뒷탄을 타고 내려가라"
rows["95:1878195011"]="신성한 부름에 따라 진실을 알고자 하는 모든 이에게 그 실체를 말씀드리겠습니다."
rows["95:189148984"]="우리는 쇼라자르 하천에서 이 사람을 찾기 위해 며칠을 보냈습니다."
rows["95:1917952427"]="네 바람의 계곡으로 물러나야 할 수도 있어요."
rows["95:1932962499"]="타란 주 신하가 우리 군대의 대부분을 데리고 떠났으니 지금 공격하는 건 어리석은 짓이야"
rows["95:1933131186"]="판다리아를 탐험해 보세요. 하지만 조심하세요. 이 땅은 경각심을 갖지 않는 사람들에게도 큰 보물과 위험을 감수합니다."
rows["95:1951186865"]="이런 상황이 발생하니까 당신이 우리에게 실리더스를 수색하여 모래 노움의 증거를 찾으라고 했던 일이 생각나는군요."
rows["95:1965437266"]="우리는 절벽의 가장자리에 걸어가고 있습니다. 우리 중 일부는 계속하기 위해 밀어붙여야 합니다."
rows["95:1979737230"]="내 경호자들을 이길 수 있었던 것 같지만, 그들은 아무튼 쓸모가 없었어요"
rows["95:1986827516"]="듀로 마나괴철로가 보강될 것이다! 울트리스 마나괴철로는 끔찍한 재앙이었어. 같은 실수를 반복하지는 않을 것이다!"
rows["95:1998149557"]="그 트롤을 돌보는 계획이 있어?"
rows["95:2000946239"]="다른 스 ⁇ 만은 \"너의 손만 불타야 한다\"고 했지"
rows["95:2002193084"]="계속 가야 하오. 악몽에서 나랄렉스 님을 구하려면 해야 할 일이 많소."
rows["95:2005822792"]="포게마스터, 적이 당신의 작전을 방해했다고 전해졌어요"
rows["95:2010137478"]="리치 왕께서는 더 많은 서리고룡을 앙그라타르로 보내길 원하신다! 그분의 기대에 보답하지 않는 놈은 내 분노와 대면하게 되리라!"
rows["95:2029073082"]="|cFFB600B8 시크'딕 파괴자|r와 |cFF815d18 시크'직 전사|r의 파도가 전투에 합류한다."
rows["95:2037442187"]="고등 교육자님과 훈련하는 특권을 얻었소"
rows["95:2051371739"]="이 복도 너머에 나랄렉스께서 발작을 일으키는 고통스러운 잠에 빠져 계시오. 너무 늦기 전에 그 분을 깨우러 갑시다."
rows["95:2061533786"]="죽었으니, 우린 자유로워졌어요."
rows["95:2063788434"]="당신의 \"황후\"가 쓰러졌어, 클라시들은 판결을 내렸어."
rows["95:2085532434"]="이거 풀는데 도움이 된다면 둘 다 쉬게 될 거야"
rows["95:2088905260"]="디폴름은 지구의 영역입니다. 여기서 죽음의 날개가 처음으로 패배했을 때 물러났다."
rows["95:209042013"]="사마바  ⁇ 이오가 잘못 된 쿼터마스터가 되잖아!$B$B그녀는 데 센진 챔피언들만..."
rows["95:2097522524"]="내 계획을 실행하려면 먼저 생명 돌을 만들어야 한다"
rows["95:2104922653"]="도와줘서 고마워 모험가님, 모그를 막는데 최선을 다해 도와줄게요"
rows["95:2117473836"]="저는 거의 Zouchin이 세상의 어둠으로부터 보호받았다고 믿게 된 자신을 속였죠."
rows["95:2121988413"]="가끔은 너무 많은 돈이 있어 고통스럽고 외로운 기분이야"
rows["95:2125790671"]="당신이 구한 이 아름다운 생명체는 섬을 보호하는 번개 공격에 면역력이 있습니다."
rows["95:2132527700"]="준비해 내 형제들아, 우린 어둠의 문을 통과하고 모든 아제로스가 무너질 거야!"
rows["95:218409358"]="위쪽에서 더 좋은 전망이 있어 피가 튀어나오지 않는 것도 빼놓을 수 없다"
rows["95:232554803"]="젠다라리, 아르헨트 십자군, 스컬지난 네가 누군지 신경쓰지 않아!"
rows["95:250753480"]="이 물에서 놀라운 크리스탈을 자라는데 촉매를 위해 더 많은 아페크시스 조각이 있어야 합니다!"
rows["95:262096744"]="프라우드무어에게 필요한 모든 지원이 필요해요"
rows["95:264952374"]="암흑의 시기에 인간들은 우리를 버렸잖아! 인간 종족의 왕자는 몸소 우리 땅을 습격했고..."
rows["95:279032822"]="미안한데, 친구, 얼라이언스의 자격증을 가진 공무원만 차량 구매를 허가할 수 있습니다."
rows["95:30549024"]="아서스! 넌 이미 수적으로 열세다! 서리한을 내려놓아라. 합당한 죽음을 안겨주겠다."
rows["95:307622062"]="당장 호박빛소나무 오두막으로 데려다 드리겠습니다! 한데, 그전에 어디 한 군데 잠시 들러야 하는데..."
rows["95:325757399"]="테렌티스의 눈은 먼 곳에  ⁇ 지 않고 시선을 돌고, 그의 마지막 순간의 슬픔을 드러내고 있습니다."
rows["95:332325361"]="'전문가'는 여전히 볼진이 죽은다고 믿어요.  ⁇ 라이 정상에서 그의 코크론 암살자들에 의해 살해당했습니다."
rows["95:335953902"]="도움 감사합니다 $p최고의 맥주를 만들지 못했지만 꽤나 모험을 했습니다."
rows["95:340099007"]="때로는 정확한 공격이 가장 강력한 적을 때릴 수 있을 뿐이다."
rows["95:35933129"]="괴물이 친구를 사귀려고 하고, 그리고 나서 BAMM... 다음엔 그가 묶여있다는 걸 알잖아!"
rows["95:368359524"]="우린 모두 판다레네야!"
rows["95:37830392"]="대흑마법사 윌프레드 피즐뱅이 다음 상대를 소환할 걸세. 기다리고 있게나."
rows["95:379651443"]="하지만, 그건 내가 본 계시와는 다르구나... 내 백성들은 그렇게 자유의 몸이 되는 것이 아니야..."
rows["95:392176982"]="내일 왕자를 잘라내려고 해요"
rows["95:408265278"]="[ph]에 서 있는 썬더 블러프우리들 썬더 블러프 케어른이 죽은 지 얼마 되지 않아 운이 좋지 않아요"
rows["95:408418601"]="스모키우드 가시의 괴물은 항상 이 때 판매하는 멋진 맛집을 가지고 있습니다."
rows["95:410893533"]="우리의 축복받은 큰 해조류인 그린 아일랜드가 여기서부터 드래곤블라이트에서 모아키 항구로 이동합니다."
rows["95:411825007"]="영웅들, 항구로 가서 해안 방어력을 없애고 이 피를 흘리는 것을 멈추게 해"
rows["95:423685105"]="아직 확실하게는 모르겠지만 이 온천에는 뭔가 이상한 점이 있어요..."
rows["95:450844952"]="아예사, 저는 그녀가 다른 판다레인을 훈련시키는 걸 봤다고 생각합니다. 스톰윈드 계속"
rows["95:464483002"]="침입자가 있다고 보고됐어요. 뭔가 특이한 걸 보시면 즉시 알려주세요!"
rows["95:468368205"]="알 수 없는 친구로군... 그리고 말해 두지만, 난 알 수 없는 친구와 엮이고 싶지 않소..."
rows["95:475783037"]="타구리 관리자는 상류 구역 상단 반지에 둥지를 틀고 있어 냄새가 빠지지 않아"
rows["95:480766597"]="두 단어: 카부름!$B$B내가 말하는 건 이 파티는 두 개 가루 덩어리만 먹으면 좋겠어"
rows["95:485687513"]="저는 포세이큰가 호드의 동맹을 오해하고 있다고 믿습니다. 잠깐... 저는 너무... 어지럼증..."
rows["95:491256021"]="너희들은 강하고 야만적이지만 항상 기억해 보라 사자는 배고픈 때에만 죽는다"
rows["95:499665633"]="내가 내 뼈에 진실이 될 것을 알고 있는 동안, 형제가 왜 그렇게 생각하는지 말해줘!"
rows["95:506132286"]="지지지는 내가 수도원 훈련 프로그램에 들어갔다고 믿기지 않을 거야!$b$b내가!"
rows["95:515935777"]="|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t 보너스 목표: 파괴자 보로후라를 물리치세요!"
rows["95:518783516"]="자부심을 가져라 용아 오늘 네가 아제로스가장 위대한 영웅이자 제 칼에"
rows["95:519958058"]="자비... 아내와 아이가 살해당했고, 친척이 사라졌고, 집이 불태워졌어요."
rows["95:532844473"]="이건 오래된 툴도저 추방이 필요해요"
rows["95:537471636"]="사실, 저는 호드의 경험이 풍부한 참전용사에게 죽음의 가장자리에서 그들을 구출했다고 들었습니다."
rows["95:555478168"]="모든 최고의 거래 스톰윈드 내 친구, 더 나은 것을 찾을 수 없을거야."
rows["95:557382329"]="이 왜자들은 오늘날 같은 존재인가? 왜들은 지구인과 다른 연결을 유지하는가?"
rows["95:570619472"]="그림 가즐러가 없었다면, 나는 드래곤 새끼들에게 날개를 뽑아낼 수 있었다."
rows["95:570839613"]="내 말 그만 해, 우리 모두에게 찌꺼기야!"
rows["95:570956871"]="내가 도와줄 수 있다면 죽음의 날개는 결코 상자를 가질 수 없을거야!"
rows["95:576377411"]="아레나에도 들어오는 배틀트론 이 쓰레기 조각이 널 덮어 버릴 때까지 기다리고 있어"
rows["95:57890654"]="우리는 그들의 인형처럼 - 우리는 춤추고 울고 싸우고 그들의 재미를 위해 어리석은 말을 합니다.\010"
rows["95:592409879"]="노예의 거... 고레게크는 큰 악귀 여왕이 한 번 물었습니다."
rows["95:598288398"]="네가 생각하는 것과 상관없이 이 세상에 네 죽음을 슬퍼하는 사람들이 있을지도 모르니까"
rows["95:621170221"]="%s 지혜의 에너지를 축복으로 소멸시키고 마법에 대항하는 파동으로 다시 방향을 바꾸죠."
rows["95:627027579"]="부상자들을 모아주세요 오늘 큰 타격을 입었습니다."
rows["95:632437242"]="당신은 우리의 물에 어리석은 침해를 했다 호드 내 폭풍의 타파로 치질게"
rows["95:634492114"]="흠, 비전 파멸자는 정말 강하지. 휠러 아저씨는 자신이 뭘 요구하고 있는지 알기는 하는 건가?"
rows["95:636710179"]="불꽃이 세상을 삼키고 폭풍이 모든 희망을 씻어내고"
rows["95:641440261"]="하르케크 장로님은 좋은 광란심장 일족이다. 내가 어릴 때 여러모로 도와주셨다. 다지크는 좋아하지 않아."
rows["95:649989503"]="참 답답도 하시군요. 뭘 하실 수나 있습니까? 저는 한창때 아버지보다 훨씬 강합니다."
