rows["95:660827435"]="셰가 판다레인을 약하게 해버렸어 이제 그들을 영원히 베일드 스텝에서 밀어내야 할 때입니다!"
rows["95:690445634"]="네 동료는 우두머리 수정뿔 코뿔소인 파룬을 찾고 있다. 녀석은 자기 형제들에게서 멀리 떨어져 있지."
rows["95:692790507"]="테일러 대령이 우리를 보내서 젊은 왕자를 찾아왔어"
rows["95:700338652"]=" ⁇ 에서 많은 것을 들었어요. 렌사이는 내가 그에게 말할 수 있는 것에 만족할 것입니다."
rows["95:703527033"]="사실이라면, 캐디 노르들링거의 철학 수업은 바로 이 계곡 아래로"
rows["95:704539656"]="다시 돌아와 포세이큰 최고 지휘관!$B$B|r|TInterface\\Icons\\ACHIEVEMENT_ZONE_SILVERPINE_01.BLP:24|t"
rows["95:707889687"]="여기서 유일한 광기는 네 거야, 코릭!"
rows["95:71063145"]="쿠야오를 찾고 있어 며칠 동안 못 봤어"
rows["95:712286387"]="잘 해줘, 반발한 폭탄 발사 원망자여"
rows["95:729250535"]="내 옆에 공부하는 시간이 끝나고 있습니다. 아흐마는 기꺼이 더 많은 것을 가르쳐 줄 것입니다."
rows["95:733596311"]="강도의 계곡 중에서 대부 겨울을 찾을 수 있을 거야 나무를 찾아봐"
rows["95:737735698"]="해리슨 존스는 현장에서 아닌 동안 스톰윈드 킵의 로얄 라이브러리에서 고고학을 가르칩니다."
rows["95:750645523"]="오너라, 스컬지베인. 누가 진짜 \"용사\" 호칭을 들을 자격이 있는지 주인님께 보여주리라!"
rows["95:761818741"]="그론에 대한 우리의 지하 운동은 흔들리지 않아야 합니다."
rows["95:762274178"]="넌 피할 수 없는 걸만 지연시켰어 되살아난 자..."
rows["95:762507452"]="활은 좋은 친구이고, 조우스는 그것을 돌봐야 할 것이고, 조우도 돌볼 것이다."
rows["95:7753473"]="뭐... 이 정도면 목걸이 하나는 만들고도 남겠지. 얼른 집에 가야겠다."
rows["95:782079714"]="아드미럴, 그들이 항복하려고 하는 것 같아요 무장하지 않고 그냥 익사하지 않으려고요"
rows["95:802087759"]="이 책에서 읽어봐요, 신실한 맹세입니다."
rows["95:808986055"]="그들의 배를 태우고, 그들의 비행장님을 죽이고, 그들의 전쟁 기계를 파괴하고, 우리의 스파이를 구해라!"
