rows["97:1816223740"]="이 짐승은 리버파우 괴물 갱단을 이끌고 엘윈의 괴물 공격을 종식시키는 열쇠가 될 수도 있습니다."
rows["97:1839833018"]="남자든 여자든 아이든... 아무도 주인님의 분노를 피할 수 없다. 다 죽은 목숨이지."
rows["97:1840727464"]="영웅이여, 이제 어찌해야 하는가? 그의 손아귀에서 벗어났지만, 여전히 필멸의 굴레에 묶인 이들은?"
rows["97:1848219635"]="사우스시 페럴과 정복은 이번 주 안에 우리와 함께 침략에 도움을 줄 것입니다."
rows["97:1850306879"]="멸망에 처한 세계의 수호자들이여, 구차한 목숨이라도 건지려면 어서 달아나라!"
rows["97:186257748"]="마법의 결과로, 네가 꿰뚫어낸 것을 거두면, 엘룬이 우리 모두에게 도움이 될 거야"
rows["97:1869011822"]="랩터 매트리하가 래프터 리드즈의 깊은 곳에 살고 있으며, 그녀의 달걀을 보호하고 있다고 합니다."
rows["97:1869216638"]="이미 집착됐어, 내가 널 신뢰해 그림 배톨로 가는 길을 확보해줄게"
rows["97:1875938686"]="하지만 그들은 살게라스의 꼬임에 넘어가 지금은 우리의 가장 강력한 적이 되었습니다."
rows["97:1891357259"]="영웅, 당신은 블랙 프린스를 방어해야 합니다."
rows["97:1896860441"]="\"그대 무리를 막으려 했을 때, 그녀는 말 그대로 '무리한 생명을 잃지 않도록' 했었습니다."
rows["97:1901324167"]="인간 중 한 명이 이 지옥의 기계를 키로 가지고 있다고"
rows["97:1902083729"]="당신 의 눈 은 당신 앞 에 있는 것 을 보지 못 하고, 그 는 당신 의 잘못된 식습관 때문 이 아닐 수 없다."
rows["97:1917068211"]="드레노르의 모든 사람들이 내 발 아래로 떨고 이 세상을 파괴하고"
rows["97:1918302689"]="자, 잠시만 그늘로 태양을 막는 건 어때?$b$b그건 정말 좋겠네"
rows["97:1920018311"]="적을 잠시 더 견제해야 돼"
rows["97:1926556337"]="|TInterface\\Icons\\INV_POTION_24.BLP:20|t말로리아크는 |cFFFF0000 빨간색|r  ⁇ 을 불에 던진다!"
rows["97:1929066060"]="이 땅을 여행하면서 많은 것을 보았는데, 나이가 많고..."
rows["97:1948986812"]="이 말은 다 말야, 와서 너의 보상을 가져가 오늘 배운 것을 기억해"
