rows["97:1968952399"]="그리고 그들과 함께, 나는 황금 로토스를 꺾고 번개왕의 이름으로 계곡을 되찾아낼 것이다!"
rows["97:1974391969"]="돈 좀 벌 수 있을 것 같아."
