rows["97:1986987443"]="해수욕장에 돌아가서 살아 있는 놈들을 데려오도록 도와줘"
rows["97:1988088965"]="연구결과를 거둔 후, 우리는 Vale에서 휴식을 취해야 합니다."
rows["97:199733677"]="그린스킨, 왜 왔는지 알아요."
