rows["97:201310172"]="옛 형제들아, 너희 시간은 짧아져요. 너희는 영원의 모래로 사라지기 전에 우리와 함께하라"
rows["97:201519365"]="너 고양이 좋아? 난 사랑해!$B$B<엘라는 갑자기 폭발하면서 놀라며 부끄러움을 자아내며 웃는다>"
rows["97:2034142358"]="어둠의 여왕께서는 최대한 많은 적을 막아내셨지만, 결국엔... 살아계셨으면 좋겠어요. 제발 도와주세요!"
rows["97:2062652005"]="판다리아에 대한 당신의 선구적인 노력이 없었다면, 이 발걸음은 불가능했을 것입니다."
rows["97:2085534313"]="%s 투하 |cFFFF0000|Hspell:107140|h[자기 유방]|h|r. 치유 에너지를 방출하기 위해 그룹!"
rows["97:2091888857"]="이 멍청이들이 이런 걸 위해 학교에 갔다는 건 믿기지 않네"
