rows["97:2109178751"]="이 첫 번째 부분은 가장 힘들죠. 열풍문으로 도착하면 길이 훨씬 더 명확해집니다."
rows["97:2119876279"]="얼마나 더 오래 지낼 수 있을 것 같냐?"
rows["97:2134750407"]="애는 날 두 번이나 당당하게 당당했지 하지만 난 도전에서 도망칠 생각은 없었어"
rows["97:2136374692"]="사우로크가 저를 흥미롭게 합니다.$b$b사실, 몇몇은 저를 \"스틱 블레이드 스티브\"라고 부르기 시작했습니다."
rows["97:2143891975"]="여러분들의 이야기를 들려드리겠습니다. Hollowstone 광부들이 포기하지 않았다는 것을 전해주실 겁니다."
rows["97:217476802"]="여기 주변 호수에는 바다 생물이 잔뜩 살고 있어. 어떻게 흘러든 건지 모르겠네... 물살에 떠밀려 온 건가?"
