rows["97:239626919"]="아직 네 시간이 아니었어 내가 살아 있는 세상으로 돌아가는 데 도움이 될 거야"
rows["97:256806251"]="<구름에 잡을 수 있지만 피즐의 손이 더 단단히 붙어 있습니다. 구름은 약간 빛납니다.>"
