rows["97:267182143"]="이승만들이 세상을 다시 만들자 우리 인종에 위협이 되는 것들이 많았습니다."
rows["97:268538304"]="스카이미스터스 글로밍과 그녀의 드래곤하크는 목자의 문에서 서쪽에 있습니다."
