rows["97:296932232"]="자네가 없었으면 승리하지 못했을 것일세. 천둥군주 요새에서 다시 얘기하도록 하세나."
rows["97:304780020"]="정말 좋은 소식입니다. 저는 여러분의 감사의 마음을 우리의 지휘관들에게 전달하겠습니다. 아제로스."
