rows["98:615438178"]="스나럴은 내가 너무 느리니까 단순하다고 부르는데, 내가 제대로 하고 싶어서 시간이 필요해"
rows["98:615776313"]="내가 그녀를 보고 싶었으면 네 비참한 밴드를  ⁇ 으로 만들었지만, 다른 곳에 필요해"
rows["98:62268198"]="날 풀어줘서 고마워해야지 곧 알게 될 거야"
rows["98:62521463"]="이럴 수가! 이곳의 주인은 나다! 우리에 비하면 너희는 아무것도 아니다! 아무것도!"
rows["98:627051250"]=" ⁇ 리야가 좋은 고향이 될지도 몰라"
rows["98:630386715"]="용감하게 될 준비가 안 됐다고 생각하지만, 곧 준비될 것 같아"
rows["98:631116235"]="\"마법의 순환이 세계에 미치는 영향\", 마지노르 뒤마 지음. 이게 바로 내가 찾던 책이야."
rows["98:647297987"]="추운 땅 근처에 너무 가까이 가지 말고 움직이는 것이 훨씬 더 힘들게 될 것입니다."
rows["98:652501227"]="미안하지만, 로나가 말을 데려다주면 정말 화가 나겠지\010길네아스의 친구들만 위한 거야!"
rows["98:653028676"]="기즈모, 왜 그냥 앉아있어요? 누가 옆에 누워있는지 알아내지 않나요?!"
rows["98:65457368"]="크리드의 암흑 마법이 내 시력을 방해하고 있어"
rows["98:677254390"]="발린다 스톤하스 캡틴이 쓰러졌어!$B$B공격 호드스톤하스 대장에게 복수를 요구해"
rows["98:680971476"]="괜찮아, 바인, 트롤을 찾아서 데 워시프를 죽이고, 네 아버지를 복수할 거야"
rows["98:684346649"]="이 영은 쓰러진 몸 위에 떠다니며 귀신적인 눈이 너한테 뚫고 지나가면서..."
rows["98:687646323"]="그래서 그는 발견한 이상한 작은 동굴 생물들을 데리고 밸리의 힘으로 왜곡했습니다."
rows["98:700588565"]="오래된 전설들은 도자니 왕조와 그들의 젊음의 풀에 대해 이야기합니다."
rows["98:706395318"]="|TInterface\\Icons\\INV_POTION_20.BLP:20|t말로리아크는 |cFF809FFE블루|r  ⁇ 을 불에 던진다!"
rows["98:709080045"]="피 한 방울도 남김없이 먹어 치워라, 아이들아. 놈들의 영혼을 잡아먹어라!"
rows["98:71535567"]="곧 갈라크론드의 뼈가 영원의 잠에서 깨어나 온 세상에 재앙을 내릴 것이다!"
rows["98:718167816"]="사자들이 움직일 수 있도록 명령할 수 있습니다.$B$B|TInterface\\Icons\\misc_arrowleft.blp:64|t"
rows["98:722216376"]="당신 잘못이 됐어, 몰센 이제부터 색을 구분해줄 수 있을 거야"
rows["98:735512745"]="감방문들이 너무 복잡하게 잠겨 있어서 제게는 이 문을 여는 주문밖에 없습니다."
rows["98:744339908"]="%s 이상한 비틀거리는 소리를 내기 시작합니다. 달의 눈물이 땅에 떨어지고 부서집니다."
rows["98:755355969"]="그들을 기지로 돌려보내라 얼라이언스 군인이 이 전쟁터에서 살아남는 걸!"
rows["98:765510050"]="호기심이 많아요, 래스타칸의 종은 할카리를 모르는 구 언어에 말을 하지 않는 거요?"
rows["98:776800218"]="구시가지 동남문 밖의 지휘 센터에서, 당신은 분기장들을 찾을 것입니다."
rows["98:777984470"]="피와 총알과 땀이 뒤범벅된 싸움이었지. 여왕은 점점 더 빠르게 공격해왔어!"
rows["98:778645278"]="부모 는 자녀 를 길 에 인도 하는 것 이다. 그러나 그 길 은 항상 자녀 들 을 어디로 인도 할 지 모른다."
rows["98:785450979"]="친절한 낯선 여러분, 이 곳을 그들의 불쾌한 존재로부터 깨끗하게 해내며 우리의 이야기를 끝으로 내버려두세요."
rows["98:785843585"]="테일드라시일을 볼 수 있을 줄은 몰랐어요. 테일드라시일에 충돌할 줄은 몰랐어요."
rows["98:794084780"]="모구지아에서 내 사람들이 죽고 있는 건 네가 벨로 가는 유일한 길을 없애는 게 아니라"
rows["98:816161599"]="그는 많은 고위 의 장로 들 이 오고 가 있는 것을 보았으며, 그 또한 이러한 축제를 매우 심각하게 받아들이는 경향이 있다."
rows["98:829739050"]="용기를 가져라!$B$B영혼사격자는 패배했고 그의 불행한 마음은 지하로 던져졌습니다!"
rows["98:838528173"]="더 큰 일이 다가오고 있다고 생각했는데 살아남기 위해서는 말론의 힘이 필요해"
rows["98:85555901"]="내면의 돌이 떨리는 소리를 들었는데, 뭔가에 대해 흥분하고 있는 것 같군."
rows["98:856973478"]="기계를 만들기에 용기가 있는 엔지니어가 있다는 것은 좋죠."
rows["98:857733460"]="우수성을 향한 길에는 많은 장애물이 있습니다."
rows["98:884275380"]="하지만 죽은 후에는... 우리는 저주받은 자의 자식이 되었네. 스컬지의 버림받은 아들딸 말일세."
rows["98:896443554"]="자비를 베풀지 말고 피의 향을 먹어라."
rows["98:896895392"]="해적! 아무도 해적에 대해 아무 말도 하지 않았어!$B$B저들을 잡지 말아주게, 보스. 난 죽기엔 너무 젊어!!!"
rows["98:900810290"]="이건 부담이지만, 내가 영향을 받지 않아야 했어야 했는데\010"
rows["98:90414042"]="기억하세요, 만약 당신이 대표를 괴롭히거나 채널을 스팸으로 보내면 당신의 계정이 해킹되거나 금지되거나 더 나쁜 경우도 있습니다."
rows["98:908627394"]="저쪽 절반에 있어요, 이 호드를 여기서 멀리 두세요. 공학 학교에서 싸우지 못해요!"
rows["98:915691378"]="일이 돌아오고 있어, 내가 여기 있는 건 임무로..."
rows["98:919956789"]="만약 C'Thun이 살아남았다면 우리의 자유는 아무 의미가 없었을 겁니다."
rows["98:925007645"]="이 모든게 아주 멀어졌다고 생각하지만, 이 계획에 따라 많은 걸 할 수 있습니다."
rows["98:926887489"]="내가 다시 조립되었으니 우리는 완벽의 시대로 돌아갈 수 있다... 티탄의 시대로 말이다!"
rows["98:943367074"]="만약  ⁇ 돌이들의 상상할 수 없는 행운이 없었다면, 그들은 모든 경주에서 차를 몰아치려버리겠죠!"
rows["98:94784039"]="이 순간을 제 아들과 함께 나누는 것이 너무 행복합니다."
rows["98:94959612"]="그들이 원하는 것은 그것뿐이라면 아마도 전쟁은 피할 수 있고, 다가올 피 흘리는 것도 막을 수 있을 것이다."
rows["98:971225795"]="이 불쾌한 냄새는 맡아본 적이 있는데... 새끼 눈표범 등에 타고는 숨어서 내 뒤를 지나간 게 바로 네 녀석이구나!"
rows["98:974492705"]="배는  ⁇ 니다. 이제 난 토스트를 제안하고 싶습니다. 걱정하지 마세요, 나는 짧고 달콤하게 유지 할 것입니다."
rows["98:975585932"]="나무의 좋은 점은 항상 다시 자라는 것입니다. 이것이 지속된 소득이라고 할 수 있습니다."
rows["98:984080741"]="점장님, 지난번에 독을 제조할 때 무기력의 뿌리를 빠트린 것 같습니다."
rows["98:995693241"]="난 이 동굴을 파괴하고 뒤쪽에서 침입할 수 있어"
rows["98:999732731"]="그대는 우리와 함께 하기를 원하느뇨 실로 우리는 이 도시에서 선지자들을 보냈으니"
rows["99:1000405940"]=" ⁇ 라이 정상에서의 혼란은 많은 무고한 사람들을 파멸시켰습니다. 그들은 우리 문 안에 보호를 찾을 것입니다."
rows["99:1000450349"]="썬더 블러프의 가장 낮은 부분에서 발견됩니다. 은행 근처에서 검색합니다."
rows["99:1010547764"]="오, 신사님, 제가 틀리지 않는다면 자오 선시커의 이야기는 우리 앞에 살아났던 것 같습니다."
rows["99:1017527747"]="래저힐은 우리 거야, 대워체프는 그로마시 홀에서 온 곳에서 불을 볼 수 있어"
rows["99:1018353366"]="그 곳, 트롤의 주머니 속 깊은 곳에 아름다운 보석이 있었습니다."
rows["99:1034922913"]="빠른 평가를 받고 그 사람이 지난 몇 시간 안에 사망했다고 판단합니다."
rows["99:1051971595"]="드래곤 영혼의 포털 연결이 깨졌어"
rows["99:1069448970"]="노련한 오크 대부분이 절망에 빠진 이유는 드레나이 아이 목소리 때문이었네. 한 번 들으면 절대로 잊을 수 없지..."
rows["99:1074178063"]="다른 종류의 조정을 할 수 있을지도 몰라"
rows["99:107972257"]="젠타브라, 당신은 소문에서 나오는 드루이드 중 한 명입니까?"
rows["99:108642870"]="코코넛 우유의 한 방울도 A-Me 01 의 눈에서 흘러나오고, 그녀는 뷔가를 마지막으로 보고 있다."
rows["99:1095587103"]="그레고르, 겁쟁이 순수한 피의 오크들이 우리 해변에서 죽어 가고 있어"
rows["99:1105214155"]="우린 군대를 데리고 여기 올 거야 가로쉬를 숨기게 해낼 수 있는지 알아"
rows["99:1109453491"]="페렐리 씨, 지난 몇 주 동안 어두운 옷을 입은 남자들이 의심스러운 활동을 보신 적이 있나요?"
rows["99:1109959113"]="네 의지도 강하지만 내 의지도 강해 보이네"
rows["99:1122371137"]="너무 늦었어, 멍청아! 고대 의지가 깨졌어. 절차는 거의 완료됐습니다!"
rows["99:1144924963"]="안 돼... 안 돼! 무슨 짓이냐? 내가 주인이야! 내 말 듣지 못해? 나란 말이야! 내가... 으아악! 놈을 억누를 수... 없...어."
rows["99:1146998252"]="왼쪽으로 보면 곤미들이 다시  ⁇ 메레건을 잡았다는 걸 알 수 있을 거야"
rows["99:1156798961"]="제 전쟁 기계를 물리쳤지만, 그 게이트는 여전히 존재합니다. 오늘 당신은 오그리마를 차지하지 않을 것입니다."
rows["99:1171080923"]="...우리가 지원하기 시작할 때 호드 그들의 작은 싸움에서 얼라이언스 친구들\010"
rows["99:1200599596"]="알 만한 분들이 왜 이러시나요. 근무 중인 군인에게 술을 제공할 수는 없습니다. 제가 사령관님께 죽는 꼴을 그렇게 보고 싶은 건가요?"
rows["99:1201005698"]="언젠가는 이야기하게 될 것이다! \"진홍빛 서광\"이 무엇인지 말해라. 그러면 목숨은 살려주겠다!"
rows["99:1238232754"]="추가적인 정보는 관리자 로켄의 명령에 의해서만 울두아르 내에 있는 저장고에서 접근할 수 있습니다."
rows["99:1248613953"]="날름이들이 가끔 수정을 캐러 오곤 한다. 우리가 놈들을 사냥하니까 지금은 오지 않는다."
rows["99:1251115080"]="아, 컨소시엄의 친구인걸 보는데 구매하는 게 좋을 것 같군요"
rows["99:1258046258"]="무슨 일이 있었지? 오... 머리가 폭발할 것 같네요."
rows["99:1259583474"]="네 돈의 대부분을 제대로 된 마사지를 위해 썼는데, 넌 절대 제대로 할 수 없어!"
rows["99:1270910636"]="파멸의 수호병은 자신들이 모시는 지옥의 군주에게 절대적으로 충성하며 세계를 파괴하는 것을 즐깁니다."
rows["99:127381886"]="아무 것도 상관없어, 케일더의 귀여운 반려동물에 손을 뻗는 만큼 멍청한 사람은 없을 것 같네"
rows["99:1274238967"]="난 어떤 보상으로 제공되는지 신경쓰지 않아, 난 뼈 폐기물에 가지 않을거야!"
rows["99:1279639723"]="땀을 보고 싶지만, 땀이 안 나오면 피가 생기게 되겠소"
rows["99:128082946"]="내가 캠프로 가자고, 내 조교인 호니츠와 얘기하면 돈을 받을 수 있어"
rows["99:1296790378"]="내 몸을 구해줘서 고마워요, 힘이 회복될 때까지 잠시 누워요"
rows["99:129736200"]="당신의 서비스는 주인님의 계획을 성취하는데 귀중한 역할을 해왔어요"
rows["99:1304004801"]="이봐요, 무슨 일인지는 모르지만, 저 무뢰한을 혼내줄 요량이라면 내 기꺼이 도와드리죠!"
rows["99:1304859398"]="이제 악마들이 처리됐으니, 우리는 새로운 기지를 만들 수 있습니다. "
rows["99:1311701645"]="좋아. 펜구스 이 녀석, 어디 있는 거냐?! 어디 나와서 놀 애인이라고 또 비웃어봐! 이 망치로 정신이 번쩍 들게 해줄 테니까!"
rows["99:1314942550"]="야우 샤르파메인은 마을 북쪽에서 당신을 기다리고 있어 사냥꾼의 길을 가르쳐 줄 수 있어"
rows["99:1331295420"]="좋아요, 그대가 가져온 이 버섯을 사용해서 수렁군주에게 새로운 먹을 거리를 줄 수 있는지 확인해 볼까요?"
rows["99:1338071499"]="이봐, 이거 먹으려 했잖아 엘라는 필요하면 더 이상 안먹겠어"
rows["99:1346138456"]="내가 네 놈에게 아무런 제재도 하지 않고 터벅터벅 걸어와서 폭풍의 심장을 넙죽 내 줄 거라 생각하진 않겠지?"
rows["99:1349084758"]="내가 그걸 믿게 하고 싶었어, 진짜로 만들어야 해"
rows["99:1357889289"]="애쉬아리 수정 하나가 쓰러졌다! 형제들이여, 리치 왕에 대한 충성을 지켜 수정을 다시 소환하라!"
rows["99:1357997943"]="우리는 모두 노스렌드에 항해할 예정이었지만, 우리 배에 심각한 수의 해충이 발견되었습니다."
rows["99:1371239206"]="아치발드, 크로스보우의 마스터 언더시티, 대 워 구에 위치하고 있습니다."
rows["99:1372071204"]="아니... 아니야... 그게 아닐 거야. 내 말이 맞지? 피도 눈물도 없는 그 시골뜨기 녀석이 도구를 되찾아 오라고 자넬 보낸 게지. 그렇지?"
rows["99:1373533333"]="잘했어 챔피언이, 이 못생긴 생물을 데려가겠다."
rows["99:1382804806"]="이 사람이 달린 포지라이트입니다. 그는 역병이 발생했을 때 사랑하는 이와 함께 로데론에서 도망쳐 왔지요."
