rows["99:404050309"]="추운 발, 내가 추측한다. 아마도 더 나은 방법은 - 당신 같은 사람들을 위해 죽음 외에는 아무것도 거기..."
rows["99:411720614"]="난 몇 가지 무기가 있어 그 정도면 벌금을 낼 수 있었지"
rows["99:433873468"]="SI: 7 잠금박스는 진동하고  ⁇ 기 시작합니다. 북쪽에서 오는 고음, 울림의 소리가 들릴 수 있습니다."
rows["99:448537353"]="우린 서로 무기를 들고 다리우스, 워크겐은 절대 기회를 잡지 못했을 거야"
rows["99:451935224"]="돈 좀 벌 수 있을 것 같아$B$B파괴의 아레나 안에 돌아다니면 어때?"
rows["99:456259841"]="키린은 진주 마을까지 도착했고, 그 마을 가장자리에 있는 일부 덤불에 숨어있는 걸 봤어요."
rows["99:461659417"]="시간 없어 쉐도파인 추적자들은 너무 가까이 있어 벨의 위치를 알아낼 수 없다"
rows["99:466428362"]="지금 이 순간, 친구들, 우리 스스로에게 물어봐야 할 것은..."
rows["99:494840575"]="성스러운 빛이여, 타락한 이들을 거짓에서 진실로, 어둠에서 빛으로, 죽음에서 영생으로 이끌어 주소서."
rows["99:510290843"]="가서 볼진과 얘기해 준비해, 이제부터 더 많이 부탁할 거야"
rows["99:5105831"]="하늘이 어두워지고 모든 것이 침묵하리라. 그때가 돼서야 너희는 죽음이 가져다주는 달콤한 평온함을 알게 되리라..."
rows["99:512847714"]="내가 아직도 리치 왕의 통제하에 있는 척하려고 해요!"
rows["99:516238592"]="코도 라이딩의 가장 훌륭한 점을 가르쳐 줄 수 있습니다. 수업을 위한 금이 충분하다면요!"
rows["99:524326880"]="이봐, 내가 여기 있는 건 뭐든 큰 거야"
rows["99:525253962"]="적어도 길니안 공학자가 한 명이라도 공예인 테라스에서 일해요"
rows["99:528912558"]="한자리 비행기는 하지만 항상  ⁇  위에 앉을 수 있어 안전합니다$B$B준비 됐어?"
rows["99:529277733"]="남자들, 그들과 함께 살지 못해요, 그리고 없이도 살지 못해요."
rows["99:544985392"]="우리 집은 사라졌지만 우리가 살아 있는 한, 여전히 집을 만들어야 합니다. 어딘가에서요."
rows["99:557321658"]="무슨 일이 일어나고 있는지 모르겠어요 다들 미쳤어!$B$B제발, 도와줄 수 있나요?"
rows["99:572214965"]="뭐야, 싸우고 싶니? 왜 난 어쩔 수 없이 주둥이?"
rows["99:572724725"]="우리 가족은 세대를 거쳐 이 도시를 지키고 있습니다."
rows["99:594574922"]="너희들의 마음을 숨기라, 너희들의 아이들을 숨기라, 너희의 남편들을 숨기라!"
rows["99:600541707"]="여기서 해야 할 일이 있지만, 누가 날 도와줄까?"
rows["99:617571281"]="이 건물들은 확실히 무너질 것입니다. 우리가 지지선을 지원하지 않으면."
rows["99:626613299"]="네, 세이카를 찾아야 해."
rows["99:638286132"]=" 실험이 실패한 것 같군 그 새끼는 완전히 맹인이 됐어"
rows["99:650123287"]="안개 은행에 항해하고, 마지막으로 봤던 건 얼라이언스 추격에... 무슨 일이 일어났는지 말하지 않죠, 선생님..."
rows["99:651417867"]="이런 일이 계속된다면 어떻게 우리가 그  ⁇ 을 계속 공급할 수 있을지 모르겠어요"
rows["99:652003986"]="권력의 본질에 대해 이야기 해 봅시다. 저는 검을 들고 있습니다."
rows["99:65890549"]="삼각으로 우리의 방어에 힘을 주길 바랍니다."
rows["99:664075507"]="하지만 호바트, 진정해 혈압이 녹아가고 있어"
rows["99:666691553"]="트로그 녀석들이 어디서 들어오는 건지 한번 알아보죠. 더 이상 침략하지 못하게 끝장을 내야겠어요!"
rows["99:667931386"]="이  ⁇ 을 따라가면 돼."
rows["99:67804422"]="얼굴 없는 사람들한테 많은 걸 잃었지만 나자나크에서 심장을 되찾는 데 성공했지"
rows["99:687402196"]="새 찌꺼기처럼 좋지만 원숭이 왕을 들어봐"
rows["99:701169837"]="그렇다, 우리는 몇 가지 어려움에 처해 있다. 어떤 어려움인지는 확실히 인지하고 있다. 그러나 문제는 그 어려움을 어떻게 해결하느냐 하는 것이다."
rows["99:709172647"]="다크월 페어는 이 도시에 왔습니다. 당신이 본 가장 흥미진진한 쇼를 경험할 수 있도록 하십시오!"
rows["99:709771059"]="눈을 뜨지 마, 전에 사람들을 공격했던 괴물이 아직 주변에 있을지도 모른다고 합니다."
rows["99:718567451"]="우리 집 유지에 대한 책임은 우리 모두의 몫이고, 심지어 고장도 가끔씩 도움을 받아야 합니다."
rows["99:718879697"]="첫 번째 씨앗은 집안에 있어요. 더 많은 씨앗을 사려면 언제라도 찾아오세요."
rows["99:724181049"]="발하라스에서 가장 좋은 사람들이야 이미르헤임으로 가는 거야"
rows["99:733520848"]="너무 많은 피를 흘렸어, 나를 잊고 케일러에게 말해"
rows["99:733843430"]=" ⁇ , 그녀의 달리는 걸 봐요, 그냥 쉬고 경치를 즐기세요."
rows["99:738824557"]="이 돈으로 좋은 장례식을 치고"
rows["99:739913009"]="난 당신에게 늑대 승마의 가장 훌륭한 점을 가르쳐 줄 수 있습니다, 당신이 수업을 덮을 수 있는 충분한 금을 가지고 있다면!"
rows["99:755545224"]="그 ⁇ 들은 보통 쉐도파인이 지켜주죠."
rows["99:756145621"]="일어나, 죽음의 날개의 아들아 내가 너에게 내 축복을 줄거야"
rows["99:76205111"]="감시의 언덕은 이상 없습니다, 스타우트맨틀 경. 그런데 달빛시내 마을에서 데피아즈단의 대규모 활동이 보고되고 있습니다."
rows["99:762342799"]="우리는 타이탄들만큼이나 오래된 발견되지 않은 낙원에서 서 있고 당신은 전쟁을 하고 싶습니까?"
rows["99:764672761"]="저는 보물 사냥꾼이고 강력한 유물을 찾고 있습니다."
rows["99:774820364"]="마스터로 가는 길에 새로운 고원을 달렸어"
rows["99:780684093"]="5시 전에는 마시지 말라고 어머니는 늘 말하셨지. 그래도, 어머니, 세상 어딘가는 5시쯤 됐을 테죠!"
rows["99:789746658"]="이런 형님, 틀릴 리가 없죠. 분명 무라딘 형님이 분명해요. 이 어린 동생을 알아보지 못하시겠어요?!"
rows["99:797995817"]="요리 능력은 너무 낮아서 연습하면 내가 아는 걸 가르쳐 줄 수 있을지도 몰라"
rows["99:81013107"]="안타깝게도, 예술적 재능 이 어느 정도 부족 합니다."
rows["99:811895187"]="|TInterface\\Icons\\inv_sword_09.blp:20|t%s는 그의 |cFFFF0000|Hspell:99350|h[Inferno Blade]|h|r를 준비합니다!"
rows["99:817151066"]="저기 오크들이 있어요 $p냄새가 나고, 우리가 사용할 수 있는 물품도 있을 것 같네요"
rows["99:83684977"]="내 포털 창작 마법은 여기 작동하지 않는 것 같군. 저 망할 나루가 이곳을 잘 지었다"
rows["99:845838941"]="우리 사이더는 야드 숲에서 많이 쓰이고 있어"
rows["99:855999114"]="이 영웅 덕분에 우리 중 몇 명이 탈출했고, 더 많은 사람들이 바이올렛 포로스로 보내졌습니다."
rows["99:868480389"]="이 견본에 사용된 광석은 아제로스의 지각 깊은 곳에서 생겨났으며 최근에 발굴되었습니다."
rows["99:869694141"]="당신도 미스터리의 학생이에요?$B$B당신이 배우고 싶다면 포털 마법을 가르쳐 줄 수 있습니다."
rows["99:870842426"]="내 형제들이 싸움을 하고 있었지 내가 할 수 있는 건 그들을 오랫동안 막는 거야$B$B- 안 돼?"
