rows["99:87578600"]="옛날에는 사냥을 위해 살았습니다. 영광, 명예...$B$B지금 상황이 너무 달라졌나요?"
rows["99:877844504"]="누가 너이고 왜 날 괴롭히고 있어?"
rows["99:882575053"]="발명가의 원반이 권한 없는 사용자의 손에 들어갔습니다. 방어 체제 프로토콜 작동 개시."
rows["99:914149402"]="만약 당신이 투쟁한다면, 당신은 죽음 전에 고통과 공포와 사랑하는 모든 사람의 손실을 직면하게 될 것입니다."
rows["99:936473764"]="절망하지 말고 거짓 빛에서 벗어나 내가 너희에게 제시하는 희망과 진리를 받아들이라"
rows["99:945511659"]="사실, 식물들은 통제되지 않고 성장하고 있고 땅들을 삼키고 있습니다. 오아시에서 발견한 것과 비슷합니다."
