rows["99:958180399"]="좋은 일이야, 신병들이 계속 오고 있어 새 칼이 필요해"
rows["99:959440933"]="카파는 거미와 파다렌에 좋지만, 가츠나 예티스나 호젠에는 좋지 않아"
